import ArgumentParser
import AudioInfrastructure
import Domain
import Foundation
import MLInfrastructure

/// `score-diarization` — run ONLY diarization on a WAV and score the predicted
/// clusters against an RTTM ground-truth file. No transcription or
/// summarization, so it is fast enough for tuning sweeps.
struct ScoreDiarization: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "score-diarization",
        abstract: "Diarize a WAV and score clusters against an RTTM file"
    )

    @Option(name: .long, help: "Path to a 16 kHz WAV file")
    var wav: String

    @Option(name: .long, help: "Path to the RTTM ground-truth file")
    var rttm: String

    @Option(name: .customLong("clustering-threshold"), help: "Override clusteringThreshold (0.5–0.9)")
    var clusteringThreshold: Float?

    @Option(name: .customLong("min-embedding-update"), help: "Override minEmbeddingUpdateDuration (seconds)")
    var minEmbeddingUpdate: Float?

    @Option(name: .customLong("num-clusters"), help: "Fix expected number of speakers")
    var numClusters: Int?

    func run() async throws {
        Term.banner()
        let wavURL = URL(fileURLWithPath: wav)
        let rttmURL = URL(fileURLWithPath: rttm)
        guard FileManager.default.fileExists(atPath: wavURL.path) else {
            Term.error("WAV not found: \(wav)")
            throw ExitCode.failure
        }
        guard FileManager.default.fileExists(atPath: rttmURL.path) else {
            Term.error("RTTM not found: \(rttm)")
            throw ExitCode.failure
        }

        let tuning = DiarizationTuning(
            clusteringThreshold: clusteringThreshold,
            minEmbeddingUpdateDuration: minEmbeddingUpdate,
            numClusters: numClusters
        )
        Term.header("SCORE-DIARIZATION: \(wavURL.lastPathComponent)")
        Term.info("Tuning", tuningDescription(tuning))

        // Load audio.
        Term.progress("Loading audio...")
        var t = CFAbsoluteTimeGetCurrent()
        let loader = AudioFileLoader()
        let samples = try await loader.loadSamples(from: wavURL)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)
        Term.info("Duration", String(format: "%.1f min (%d samples)", Double(samples.count) / 16000 / 60, samples.count))

        // Diarize only.
        let diarizer = FluidDiarizationPlugin(tuning: tuning)
        Term.progress("Loading diarization model...")
        t = CFAbsoluteTimeGetCurrent()
        try await diarizer.prepare()
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Diarizing speakers...")
        t = CFAbsoluteTimeGetCurrent()
        let speakers = try await diarizer.diarize(samples: samples, sampleRate: 16000)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        // Score.
        let reference = try RTTMParser.parse(contentsOf: rttmURL)
        let score = DiarizationScore.compute(predicted: speakers, reference: reference)
        score.printReport()
        Term.success("Scoring complete")
    }

    private func tuningDescription(_ tuning: DiarizationTuning) -> String {
        var parts: [String] = []
        if let c = tuning.clusteringThreshold { parts.append("clusteringThreshold=\(c)") }
        if let m = tuning.minEmbeddingUpdateDuration { parts.append("minEmbeddingUpdate=\(m)") }
        if let n = tuning.numClusters { parts.append("numClusters=\(n)") }
        return parts.isEmpty ? "FluidAudio defaults (no overrides)" : parts.joined(separator: ", ")
    }
}

import FluidAudio

// MARK: - DiarizationTuning

/// Optional overrides for the FluidAudio diarization clustering pipeline.
///
/// Each field is `nil` by default, meaning "use the FluidAudio default".
/// A default-constructed `DiarizationTuning` therefore produces behaviour
/// byte-identical to constructing `DiarizerManager()` with no config.
///
/// Only the fields worth sweeping during tuning are exposed; add more from
/// `DiarizerConfig` here as tuning needs grow.
public struct DiarizationTuning: Sendable, Equatable {
    /// Cosine-distance threshold for merging speaker embeddings (0.5–0.9).
    /// Lower merges less aggressively → more predicted clusters.
    public var clusteringThreshold: Float?

    /// Minimum segment duration (seconds) before a segment contributes to a
    /// speaker's running embedding. Higher ignores short noisy turns.
    public var minEmbeddingUpdateDuration: Float?

    /// Fixed expected number of speakers. `nil` keeps FluidAudio's automatic
    /// mode (`numClusters == -1`).
    public var numClusters: Int?

    public init(
        clusteringThreshold: Float? = nil,
        minEmbeddingUpdateDuration: Float? = nil,
        numClusters: Int? = nil
    ) {
        self.clusteringThreshold = clusteringThreshold
        self.minEmbeddingUpdateDuration = minEmbeddingUpdateDuration
        self.numClusters = numClusters
    }
}

// MARK: - Mapping

/// Pure mapping from `DiarizationTuning` overrides to a FluidAudio
/// `DiarizerConfig`.
///
/// Starts from `DiarizerConfig.default` and overrides only the non-nil
/// fields. A default `DiarizationTuning` returns a config equal to
/// `DiarizerConfig.default`, preserving today's exact behaviour.
func makeDiarizerConfig(from tuning: DiarizationTuning) -> DiarizerConfig {
    var config = DiarizerConfig.default
    if let clusteringThreshold = tuning.clusteringThreshold {
        config.clusteringThreshold = clusteringThreshold
    }
    if let minEmbeddingUpdateDuration = tuning.minEmbeddingUpdateDuration {
        config.minEmbeddingUpdateDuration = minEmbeddingUpdateDuration
    }
    if let numClusters = tuning.numClusters {
        config.numClusters = numClusters
    }
    return config
}

/// Clustering overrides applied when constructing the `DiarizerManager`.
/// A default `DiarizationTuning` yields FluidAudio's built-in defaults.
private let tuning: DiarizationTuning

// MARK: - Init

/// - Parameters:
///   - inferenceTimeout: Per-call timeout for `performCompleteDiarization`.
///     Defaults to 120 seconds.
///   - tuning: Optional clustering overrides. Defaults to `.init()` — every
///     field nil, i.e. FluidAudio's built-in defaults (behaviour
///     byte-identical to constructing a bare `DiarizerManager()`).
public init(
    inferenceTimeout: Duration = TimeoutConfig.diarizationInference,
    tuning: DiarizationTuning = .init()
) {
    self.inferenceTimeout = inferenceTimeout
    self.tuning = tuning
    testInferenceFunction = nil
}

/// Internal initializer for timeout unit tests. Bypasses DiarizerManager entirely.
init(
    inferenceTimeout: Duration,
    testInference: @escaping @Sendable ([Float], Int) async throws -> [SpeakerSegment]
) {
    self.inferenceTimeout = inferenceTimeout
    self.tuning = .init()
    testInferenceFunction = testInference
}

/// Exposes `inferenceTimeout` for test assertions only.
var inferenceTimeoutForTesting: Duration {
    inferenceTimeout
}

// MARK: - DiarizationEngine

public func prepare() async throws {
    guard diarizer == nil else {
        logger.info("Diarizer already initialized — skipping")
        return
    }

    logger.info("Downloading FluidAudio diarizer models")
    do {
        let models = try await withTimeout(TimeoutConfig.modelLoad) {
            try await DiarizerModels.downloadIfNeeded()
        }

    // Start first call — runs the slow test inference function
    async let firstResult: [SpeakerSegment] = try plugin.diarize(samples: samples, sampleRate: 16000)

    // Wait for the signal that inference started (deterministic, no sleep)
    for await _ in signalStream { break }

    // Second concurrent call must throw .inferenceFailed (in-flight guard)
    var secondThrewInferenceFailed = false
    do {
        _ = try await plugin.diarize(samples: samples, sampleRate: 16000)
    } catch TranscriptionError.inferenceFailed {
        secondThrewInferenceFailed = true
    } catch {}

    #expect(secondThrewInferenceFailed, "Second concurrent diarize() must throw .inferenceFailed")

    // First call should complete cleanly
    _ = try await firstResult
}

