/// fields. A default `DiarizationTuning` returns a config equal to
/// `DiarizerConfig.default`, preserving today's exact behaviour.
func makeDiarizerConfig(from tuning: DiarizationTuning) -> DiarizerConfig {
    var config = DiarizerConfig.default
    if let clusteringThreshold = tuning.clusteringThreshold {
        config.clusteringThreshold = clusteringThreshold
    }
    if let minEmbeddingUpdateDuration = tuning.minEmbeddingUpdateDuration {
        config.minEmbeddingUpdateDuration = minEmbeddingUpdateDuration
    }
    if let numClusters = tuning.numClusters {
        config.numClusters = numClusters
    }
    return config
}

