import ArgumentParser
import AudioInfrastructure
import Domain
import Foundation
import MLInfrastructure

/// `score-diarization` — run ONLY diarization on a WAV and score the predicted
/// clusters against an RTTM ground-truth file. No transcription or
/// summarization, so it is fast enough for tuning sweeps.
struct ScoreDiarization: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "score-diarization",
        abstract: "Diarize a WAV and score clusters against an RTTM file"
    )

    @Option(name: .long, help: "Path to a 16 kHz WAV file")
    var wav: String

    @Option(name: .long, help: "Path to the RTTM ground-truth file")
    var rttm: String

    @Option(name: .customLong("clustering-threshold"), help: "Override clusteringThreshold (0.5–0.9)")
    var clusteringThreshold: Float?

    @Option(name: .customLong("min-embedding-update"), help: "Override minEmbeddingUpdateDuration (seconds)")
    var minEmbeddingUpdate: Float?

    @Option(name: .customLong("num-clusters"), help: "Fix expected number of speakers")
    var numClusters: Int?

    @Flag(name: .long, help: "Also score the oracle assignment (each predicted segment relabeled with its max-overlap reference speaker) — the clustering ceiling for this segmentation")
    var oracle = false

    func run() async throws {
        Term.banner()
        let wavURL = URL(fileURLWithPath: wav)
        let rttmURL = URL(fileURLWithPath: rttm)
        guard FileManager.default.fileExists(atPath: wavURL.path) else {
            Term.error("WAV not found: \(wav)")
            throw ExitCode.failure
        }
        guard FileManager.default.fileExists(atPath: rttmURL.path) else {
            Term.error("RTTM not found: \(rttm)")
            throw ExitCode.failure
        }

        // Start from the shipping product tuning so a no-flags run measures
        // exactly what production runs; flags override individual fields.
        // To measure FluidAudio stock defaults, pass the stock values
        // explicitly (e.g. --clustering-threshold 0.70).
        var tuning = DiarizationTuning.recommended
        if let clusteringThreshold { tuning.clusteringThreshold = clusteringThreshold }
        if let minEmbeddingUpdate { tuning.minEmbeddingUpdateDuration = minEmbeddingUpdate }
        if let numClusters { tuning.numClusters = numClusters }
        Term.header("SCORE-DIARIZATION: \(wavURL.lastPathComponent)")
        Term.info("Tuning", tuningDescription(tuning))

        // Load audio.
        Term.progress("Loading audio...")
        var t = CFAbsoluteTimeGetCurrent()
        let loader = AudioFileLoader()
        let samples = try await loader.loadSamples(from: wavURL)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)
        Term.info("Duration", String(format: "%.1f min (%d samples)", Double(samples.count) / 16000 / 60, samples.count))

        // Diarize only.
        let diarizer = FluidDiarizationPlugin(tuning: tuning)
        Term.progress("Loading diarization model...")
        t = CFAbsoluteTimeGetCurrent()
        try await diarizer.prepare()
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Diarizing speakers...")
        t = CFAbsoluteTimeGetCurrent()
        let speakers = try await diarizer.diarize(samples: samples, sampleRate: 16000)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        // Score.
        let reference = try RTTMParser.parse(contentsOf: rttmURL)
        let score = DiarizationScore.compute(predicted: speakers, reference: reference)
        score.printReport()

        if oracle {
            Term.header("ORACLE CEILING (same segments, true labels)")
            let relabeled = DiarizationScore.oracleRelabel(predicted: speakers, reference: reference)
            let ceiling = DiarizationScore.compute(predicted: relabeled, reference: reference)
            ceiling.printReport()
        }
        Term.success("Scoring complete")
    }

    private func tuningDescription(_ tuning: DiarizationTuning) -> String {
        var parts: [String] = []
        if let c = tuning.clusteringThreshold { parts.append("clusteringThreshold=\(c)") }
        if let m = tuning.minEmbeddingUpdateDuration { parts.append("minEmbeddingUpdate=\(m)") }
        if let n = tuning.numClusters { parts.append("numClusters=\(n)") }
        return parts.isEmpty ? "FluidAudio defaults (no overrides)" : parts.joined(separator: ", ") + (tuning == .recommended ? " (product default)" : "")
    }
}

