/// Experimental path: FluidAudio's `OfflineDiarizerManager` (pyannote
/// community-1 segmentation + VBx clustering), driven directly — this
/// engine is NOT wired into the product. Community defaults unless
/// overridden by --vbx-* / --min-speakers / --max-speakers.
private func diarizeOffline(samples: [Float]) async throws -> [SpeakerSegment] {
    var config = OfflineDiarizerConfig()
    if let vbxThreshold { config.clustering.threshold = vbxThreshold }
    if let vbxFa { config.clustering.warmStartFa = vbxFa }
    if let vbxFb { config.clustering.warmStartFb = vbxFb }
    if let minSpeakers { config.clustering.minSpeakers = minSpeakers }
    if let maxSpeakers { config.clustering.maxSpeakers = maxSpeakers }
    if let numClusters { config.clustering.numSpeakers = numClusters }
    Term.info(
        "Engine",
        "offline VBx — threshold=\(config.clustering.threshold) Fa=\(config.clustering.warmStartFa) "
            + "Fb=\(config.clustering.warmStartFb) speakers=\(config.clustering.minSpeakers.map(String.init) ?? "auto")"
            + "…\(config.clustering.maxSpeakers.map(String.init) ?? "auto")"
            + (config.clustering.numSpeakers.map { " fixed=\($0)" } ?? "")
    )

    let manager = OfflineDiarizerManager(config: config)
    Term.progress("Loading offline diarization models...")
    var t = CFAbsoluteTimeGetCurrent()
    try await manager.prepareModels()
    Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

    Term.progress("Diarizing speakers (VBx)...")
    t = CFAbsoluteTimeGetCurrent()
    let result = try await manager.process(audio: samples)
    Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

    return result.segments.map { seg in
        SpeakerSegment(
            speakerId: SpeakerID(seg.speakerId),
            startTime: TimeInterval(seg.startTimeSeconds),
            endTime: TimeInterval(seg.endTimeSeconds),
            confidence: Double(seg.qualityScore)
        )
    }
}

