import ArgumentParser
import AudioInfrastructure
import Domain
import FluidAudio
import Foundation
import MLInfrastructure

/// `score-diarization` — run ONLY diarization on a WAV and score the predicted
/// clusters against an RTTM ground-truth file. No transcription or
/// summarization, so it is fast enough for tuning sweeps.
struct ScoreDiarization: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "score-diarization",
        abstract: "Diarize a WAV and score clusters against an RTTM file"
    )

    @Option(name: .long, help: "Path to a 16 kHz WAV file")
    var wav: String

    @Option(name: .long, help: "Path to the RTTM ground-truth file")
    var rttm: String

    @Option(name: .customLong("clustering-threshold"), help: "Override clusteringThreshold (0.5–0.9)")
    var clusteringThreshold: Float?

    @Option(name: .customLong("min-embedding-update"), help: "Override minEmbeddingUpdateDuration (seconds)")
    var minEmbeddingUpdate: Float?

    @Option(name: .customLong("num-clusters"), help: "Fix expected number of speakers")
    var numClusters: Int?

    @Flag(name: .long, help: "Also score the oracle assignment (each predicted segment relabeled with its max-overlap reference speaker) — the clustering ceiling for this segmentation")
    var oracle = false

    enum Engine: String, ExpressibleByArgument {
        /// Production path: `FluidDiarizationPlugin` (streaming DiarizerManager).
        case streaming
        /// Experimental: FluidAudio `OfflineDiarizerManager` (VBx clustering).
        case offline
    }

    @Option(name: .long, help: "Diarization engine: streaming (production) or offline (VBx)")
    var engine: Engine = .streaming

    @Option(name: .customLong("vbx-threshold"), help: "[offline] AHC euclidean distance threshold (community default 0.6)")
    var vbxThreshold: Double?

    @Option(name: .customLong("vbx-fa"), help: "[offline] VBx warm-start Fa, acoustic precision (community default 0.07)")
    var vbxFa: Double?

    @Option(name: .customLong("vbx-fb"), help: "[offline] VBx warm-start Fb, recall (community default 0.8)")
    var vbxFb: Double?

    @Option(name: .customLong("min-speakers"), help: "[offline] Minimum number of speakers")
    var minSpeakers: Int?

    @Option(name: .customLong("max-speakers"), help: "[offline] Maximum number of speakers")
    var maxSpeakers: Int?

    @Option(name: .customLong("step-ratio"), help: "[offline] Segmentation window step ratio (community 0.2 = 2x speed / ~1.4% worse DER; pyannote-accurate 0.1)")
    var stepRatio: Double?

    @Option(name: .customLong("min-duration-on"), help: "[offline] Minimum speech duration in seconds (community 0.0)")
    var minDurationOn: Double?

    @Option(name: .customLong("min-duration-off"), help: "[offline] Minimum silence duration to split segments (community 0.0)")
    var minDurationOff: Double?

    @Option(name: .customLong("min-segment-duration"), help: "[offline] Minimum segment duration for embedding extraction")
    var minSegmentDuration: Double?

    @Flag(name: .customLong("non-exclusive"), help: "[offline] Keep overlapping output segments (disable exclusiveSegments trimming)")
    var nonExclusive = false

    @Flag(name: .customLong("include-overlap-embeddings"), help: "[offline] Do NOT mask overlapped speech during embedding extraction")
    var includeOverlapEmbeddings = false

    func run() async throws {
        Term.banner()
        let wavURL = URL(fileURLWithPath: wav)
        let rttmURL = URL(fileURLWithPath: rttm)
        guard FileManager.default.fileExists(atPath: wavURL.path) else {
            Term.error("WAV not found: \(wav)")
            throw ExitCode.failure
        }
        guard FileManager.default.fileExists(atPath: rttmURL.path) else {
            Term.error("RTTM not found: \(rttm)")
            throw ExitCode.failure
        }

        Term.header("SCORE-DIARIZATION: \(wavURL.lastPathComponent)")

        // Load audio.
        Term.progress("Loading audio...")
        let t = CFAbsoluteTimeGetCurrent()
        let loader = AudioFileLoader()
        let samples = try await loader.loadSamples(from: wavURL)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)
        Term.info("Duration", String(format: "%.1f min (%d samples)", Double(samples.count) / 16000 / 60, samples.count))

        let speakers: [SpeakerSegment]
        switch engine {
        case .streaming:
            speakers = try await diarizeStreaming(samples: samples)
        case .offline:
            speakers = try await diarizeOffline(samples: samples)
        }

        // Score.
        let reference = try RTTMParser.parse(contentsOf: rttmURL)
        let score = DiarizationScore.compute(predicted: speakers, reference: reference)
        score.printReport()

        if oracle {
            Term.header("ORACLE CEILING (same segments, true labels)")
            let relabeled = DiarizationScore.oracleRelabel(predicted: speakers, reference: reference)
            let ceiling = DiarizationScore.compute(predicted: relabeled, reference: reference)
            ceiling.printReport()
        }
        Term.success("Scoring complete")
    }

    // MARK: - Engines

    /// Production path: `FluidDiarizationPlugin` with the shipping tuning,
    /// so a no-flags run measures exactly what production runs; flags
    /// override individual fields. To measure FluidAudio stock defaults,
    /// pass the stock values explicitly (e.g. --clustering-threshold 0.70).
    private func diarizeStreaming(samples: [Float]) async throws -> [SpeakerSegment] {
        var tuning = DiarizationTuning.recommended
        if let clusteringThreshold { tuning.clusteringThreshold = clusteringThreshold }
        if let minEmbeddingUpdate { tuning.minEmbeddingUpdateDuration = minEmbeddingUpdate }
        if let numClusters { tuning.numClusters = numClusters }
        Term.info("Engine", "streaming — \(tuningDescription(tuning))")

        let diarizer = FluidDiarizationPlugin(tuning: tuning)
        Term.progress("Loading diarization model...")
        var t = CFAbsoluteTimeGetCurrent()
        try await diarizer.prepare()
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Diarizing speakers...")
        t = CFAbsoluteTimeGetCurrent()
        let speakers = try await diarizer.diarize(samples: samples, sampleRate: 16000)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)
        return speakers
    }

    /// Experimental path: FluidAudio's `OfflineDiarizerManager` (pyannote
    /// community-1 segmentation + VBx clustering), driven directly — this
    /// engine is NOT wired into the product. Community defaults unless
    /// overridden by --vbx-* / --min-speakers / --max-speakers.
    private func diarizeOffline(samples: [Float]) async throws -> [SpeakerSegment] {
        var config = OfflineDiarizerConfig()
        if let vbxThreshold { config.clustering.threshold = vbxThreshold }
        if let vbxFa { config.clustering.warmStartFa = vbxFa }
        if let vbxFb { config.clustering.warmStartFb = vbxFb }
        if let minSpeakers { config.clustering.minSpeakers = minSpeakers }
        if let maxSpeakers { config.clustering.maxSpeakers = maxSpeakers }
        if let numClusters { config.clustering.numSpeakers = numClusters }
        Term.info(
            "Engine",
            "offline VBx — threshold=\(config.clustering.threshold) Fa=\(config.clustering.warmStartFa) "
                + "Fb=\(config.clustering.warmStartFb) speakers=\(config.clustering.minSpeakers.map(String.init) ?? "auto")"
                + "…\(config.clustering.maxSpeakers.map(String.init) ?? "auto")"
                + (config.clustering.numSpeakers.map { " fixed=\($0)" } ?? "")
        )

        let manager = OfflineDiarizerManager(config: config)
        Term.progress("Loading offline diarization models...")
        var t = CFAbsoluteTimeGetCurrent()
        try await manager.prepareModels()
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Diarizing speakers (VBx)...")
        t = CFAbsoluteTimeGetCurrent()
        let result = try await manager.process(audio: samples)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        return result.segments.map { seg in
            SpeakerSegment(
                speakerId: SpeakerID(seg.speakerId),
                startTime: TimeInterval(seg.startTimeSeconds),
                endTime: TimeInterval(seg.endTimeSeconds),
                confidence: Double(seg.qualityScore)
            )
        }
    }

    private func tuningDescription(_ tuning: DiarizationTuning) -> String {
        var parts: [String] = []
        if let c = tuning.clusteringThreshold { parts.append("clusteringThreshold=\(c)") }
        if let m = tuning.minEmbeddingUpdateDuration { parts.append("minEmbeddingUpdate=\(m)") }
        if let n = tuning.numClusters { parts.append("numClusters=\(n)") }
        return parts.isEmpty ? "FluidAudio defaults (no overrides)" : parts.joined(separator: ", ") + (tuning == .recommended ? " (product default)" : "")
    }
}

