import Domain
import FluidAudio
import Foundation

// MARK: - Per-reference-speaker breakdown

/// How well a single ground-truth speaker is captured by the prediction.
struct ReferenceSpeakerScore {
    let speaker: String
    /// Total ground-truth speech time for this speaker (seconds).
    let referenceTime: Double
    /// Predicted cluster with the largest overlap of this speaker.
    let bestCluster: String
    /// Fraction of `referenceTime` covered by `bestCluster` (0…1).
    let bestClusterCoverage: Double
    /// Number of distinct predicted clusters that each cover ≥10% of
    /// `referenceTime`. >1 means this speaker was split across clusters.
    let coveringClusterCount: Int
}

// MARK: - Aggregate score

/// Result of scoring a diarization prediction against RTTM ground truth.
struct DiarizationScore {
    /// Time-weighted aggregate cluster purity (0…1). See `compute` for the
    /// exact formula.
    let aggregatePurity: Double
    let predictedClusterCount: Int
    let referenceSpeakerCount: Int
    /// Frame-wise DER fraction (0…1) from FluidAudio's Hungarian-matched
    /// `DiarizationDER`, computed with no collar.
    let der: Double
    let perSpeaker: [ReferenceSpeakerScore]
    /// Hungarian `predictedCluster → referenceSpeaker` label mapping.
    let mapping: [String: String]

    // MARK: Computation

    /// Score `predicted` speaker segments against `reference` RTTM turns.
    ///
    /// **Aggregate time-weighted purity** — for each predicted cluster `c`,
    /// let `overlap(c, r)` be the total temporal overlap between `c`'s
    /// segments and reference speaker `r`'s turns. Let
    /// `total(c) = Σ_r overlap(c, r)` (the cluster's overlapped time) and
    /// `best(c) = max_r overlap(c, r)` (its majority reference speaker's
    /// overlap). Then
    ///
    ///     aggregatePurity = Σ_c best(c) / Σ_c total(c)
    ///
    /// which is the standard time-weighted mean of per-cluster purity
    /// `best(c) / total(c)`, weighting each cluster by its overlapped time.
    static func compute(
        predicted: [SpeakerSegment],
        reference: [RTTMTurn]
    ) -> DiarizationScore {
        let predictedByCluster = Dictionary(grouping: predicted, by: { $0.speakerId.rawValue })
        let referenceBySpeaker = Dictionary(grouping: reference, by: { $0.speaker })

        // overlap[cluster][refSpeaker] = total overlapped seconds.
        var overlap: [String: [String: Double]] = [:]
        for (cluster, segments) in predictedByCluster {
            var row: [String: Double] = [:]
            for (refSpeaker, turns) in referenceBySpeaker {
                var acc = 0.0
                for seg in segments {
                    for turn in turns {
                        acc += Self.overlapSeconds(
                            aStart: seg.startTime, aEnd: seg.endTime,
                            bStart: turn.start, bEnd: turn.end
                        )
                    }
                }
                if acc > 0 { row[refSpeaker] = acc }
            }
            overlap[cluster] = row
        }

        // Aggregate purity: Σ best(c) / Σ total(c).
        var sumBest = 0.0
        var sumTotal = 0.0
        for (_, row) in overlap {
            let total = row.values.reduce(0, +)
            let best = row.values.max() ?? 0
            sumBest += best
            sumTotal += total
        }
        let purity = sumTotal > 0 ? sumBest / sumTotal : 0

        // Per-reference-speaker breakdown.
        var perSpeaker: [ReferenceSpeakerScore] = []
        for (refSpeaker, turns) in referenceBySpeaker {
            let refTime = turns.reduce(0.0) { $0 + $1.duration }
            // overlap of each cluster with this reference speaker.
            var clusterOverlaps: [(cluster: String, seconds: Double)] = []
            for (cluster, row) in overlap {
                if let secs = row[refSpeaker], secs > 0 {
                    clusterOverlaps.append((cluster, secs))
                }
            }
            let best = clusterOverlaps.max(by: { $0.seconds < $1.seconds })
            let coverage = (refTime > 0 && best != nil) ? best!.seconds / refTime : 0
            let coveringCount = clusterOverlaps.filter {
                refTime > 0 && $0.seconds / refTime >= 0.10
            }.count
            perSpeaker.append(
                ReferenceSpeakerScore(
                    speaker: refSpeaker,
                    referenceTime: refTime,
                    bestCluster: best?.cluster ?? "—",
                    bestClusterCoverage: coverage,
                    coveringClusterCount: coveringCount
                )
            )
        }
        perSpeaker.sort { $0.speaker < $1.speaker }

        // DER via FluidAudio's Hungarian-matched scorer (no collar).
        let refSegs = reference.map {
            DERSpeakerSegment(speaker: $0.speaker, start: $0.start, end: $0.end)
        }
        let hypSegs = predicted.map {
            DERSpeakerSegment(speaker: $0.speakerId.rawValue, start: $0.startTime, end: $0.endTime)
        }
        let derResult = DiarizationDER.compute(ref: refSegs, hyp: hypSegs)

        return DiarizationScore(
            aggregatePurity: purity,
            predictedClusterCount: predictedByCluster.count,
            referenceSpeakerCount: referenceBySpeaker.count,
            der: derResult.der,
            perSpeaker: perSpeaker,
            mapping: derResult.mapping
        )
    }

    private static func overlapSeconds(
        aStart: Double, aEnd: Double, bStart: Double, bEnd: Double
    ) -> Double {
        max(0, min(aEnd, bEnd) - max(aStart, bStart))
    }

    // MARK: Oracle assignment

    /// Sentinel cluster label for predicted segments with zero reference
    /// overlap. These are pure false-alarm time: no relabeling can help them,
    /// and grouping them under one label keeps them out of every real
    /// speaker's cluster.
    static let oracleFalseAlarmLabel = "ORACLE-FA"

    /// Relabel each predicted segment with the reference speaker that
    /// temporally overlaps it most — the *oracle assignment*. Scoring the
    /// relabeled hypothesis gives the ceiling any clustering algorithm could
    /// reach on this exact segmentation: residual impurity/DER comes from
    /// segment boundaries, missed speech, false alarms, and overlapped
    /// speech, not from cluster assignment.
    static func oracleRelabel(
        predicted: [SpeakerSegment],
        reference: [RTTMTurn]
    ) -> [SpeakerSegment] {
        let referenceBySpeaker = Dictionary(grouping: reference, by: { $0.speaker })
        return predicted.map { seg in
            var bestSpeaker = oracleFalseAlarmLabel
            var bestSeconds = 0.0
            for (refSpeaker, turns) in referenceBySpeaker {
                var acc = 0.0
                for turn in turns {
                    acc += overlapSeconds(
                        aStart: seg.startTime, aEnd: seg.endTime,
                        bStart: turn.start, bEnd: turn.end
                    )
                }
                // Deterministic tie-break: larger overlap wins, then
                // lexicographically smaller speaker name.
                if acc > bestSeconds || (acc == bestSeconds && acc > 0 && refSpeaker < bestSpeaker) {
                    bestSeconds = acc
                    bestSpeaker = refSpeaker
                }
            }
            return SpeakerSegment(
                speakerId: SpeakerID(bestSpeaker),
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }
    }
}

// MARK: - Rendering

extension DiarizationScore {
    /// Print a compact scoring table to stdout using the shared `Term` styling.
    func printReport() {
        Term.header("DIARIZATION SCORE (vs RTTM)")
        Term.metric(
            "Aggregate purity",
            String(format: "%.1f%%", aggregatePurity * 100),
            color: aggregatePurity >= 0.85 ? Term.green : Term.yellow
        )
        Term.metric(
            "DER (no collar)",
            String(format: "%.1f%%", der * 100),
            color: der <= 0.30 ? Term.green : Term.yellow
        )
        Term.metric(
            "Clusters",
            "\(predictedClusterCount) predicted vs \(referenceSpeakerCount) reference",
            color: predictedClusterCount == referenceSpeakerCount ? Term.green : Term.yellow
        )

        Term.subheader("Per reference speaker")
        print("    \(Term.dim)\(pad("speaker", 11))  \(pad("ref(s)", 8))  \(pad("best-cluster", 14))  cover    #clusters≥10%\(Term.reset)")
        for s in perSpeaker {
            let color = s.coveringClusterCount > 1 ? Term.yellow : Term.green
            let speaker = pad(s.speaker, 11)
            let refTime = pad(String(format: "%.1f", s.referenceTime), 8)
            let cluster = pad(s.bestCluster, 14)
            let cover = pad(String(format: "%.1f%%", s.bestClusterCoverage * 100), 6)
            print("    \(color)\(speaker)\(Term.reset)  \(refTime)  \(cluster)  \(cover)   \(color)\(s.coveringClusterCount)\(Term.reset)")
        }
    }

    private func pad(_ s: String, _ width: Int) -> String {
        s.count >= width ? s : s + String(repeating: " ", count: width - s.count)
    }
}

