/// Multipass: K restarts of the offline VBx engine + consensus-medoid
/// selection (see `MultipassDiarizer`). Uses the same config flags as
/// `--engine offline`.
private func diarizeMultipass(samples: [Float]) async throws -> [SpeakerSegment] {
    let config = offlineConfig()
    Term.info("Engine", "multipass — \(restarts) VBx restarts, consensus medoid")
    Term.progress("Diarizing (\(restarts) passes)...")
    let t = CFAbsoluteTimeGetCurrent()
    let result = try await MultipassDiarizer.diarize(
        samples: samples, config: config, restarts: restarts
    )
    Term.progressDone(CFAbsoluteTimeGetCurrent() - t)
    for run in result.runs {
        let marker = run.index == result.medoidIndex ? "◀ medoid" : ""
        Term.info(
            "Pass \(run.index + 1)",
            String(
                format: "%d clusters, consensus %.3f %@",
                run.clusterCount, run.consensus, marker
            )
        )
    }
    return result.segments
}

