    /// Run `restarts` independent VBx passes over `samples` and return the
    /// medoid run's segments. The manager (and its loaded models) is reused
    /// across passes; only clustering initialization varies run-to-run.
    static func diarize(
        samples: [Float],
        config: OfflineDiarizerConfig,
        restarts: Int,
        mergeThreshold: Double? = nil,
        progress: (String) -> Void = { _ in }
    ) async throws -> Result {
        precondition(restarts >= 1, "need at least one restart")

        var config = config
        if mergeThreshold != nil { config.exposeChunkEmbeddings = true }
        let manager = OfflineDiarizerManager(config: config)
        try await manager.prepareModels()

        var allSegments: [[SpeakerSegment]] = []
        var allChunkEmbeddings: [[ChunkEmbedding]] = []
        for runIndex in 0..<restarts {
            let result = try await manager.process(audio: samples)
            let segments = result.segments.map { seg in
                SpeakerSegment(
                    speakerId: SpeakerID(seg.speakerId),
                    startTime: TimeInterval(seg.startTimeSeconds),
                    endTime: TimeInterval(seg.endTimeSeconds),
                    confidence: Double(seg.qualityScore)
                )
            }
            allSegments.append(segments)
            allChunkEmbeddings.append(result.chunkEmbeddings ?? [])
            let clusters = Set(segments.map(\.speakerId)).count
            progress("pass \(runIndex + 1)/\(restarts): \(segments.count) segments, \(clusters) clusters")
        }

        let duration = Double(samples.count) / 16_000.0
        let labelings = allSegments.map { frameLabels(segments: $0, duration: duration) }

        // Mean pairwise agreement of each run with all others.
        var outcomes: [RunOutcome] = allSegments.enumerated().map { index, segments in
            RunOutcome(
                index: index,
                segments: segments,
                consensus: 1.0,
                clusterCount: Set(segments.map(\.speakerId)).count
            )
        }
        if restarts > 1 {
            var pairAgreement = [[Double]](
                repeating: [Double](repeating: 1.0, count: restarts), count: restarts
            )
            for a in 0..<restarts {
                for b in (a + 1)..<restarts {
                    let agreement = coAssociationAgreement(labelings[a], labelings[b])
                    pairAgreement[a][b] = agreement
                    pairAgreement[b][a] = agreement
                }
            }
            for a in 0..<restarts {
                let others = (0..<restarts).filter { $0 != a }.map { pairAgreement[a][$0] }
                outcomes[a].consensus = others.reduce(0, +) / Double(others.count)
            }
        }

        let medoid = outcomes.max(by: { lhs, rhs in
            (lhs.consensus, -Double(lhs.index)) < (rhs.consensus, -Double(rhs.index))
        })!
        return Result(segments: medoid.segments, runs: outcomes, medoidIndex: medoid.index)
    }

    // MARK: - Frame consensus

    /// Discretize a segmentation into per-frame cluster indices. `nil` means
    /// no speech in that frame. When segments overlap a frame, the one
    /// covering more of it wins.
    static func frameLabels(segments: [SpeakerSegment], duration: Double) -> [Int?] {
        let frameCount = max(1, Int((duration / frameDuration).rounded(.up)))
        var clusterIndex: [String: Int] = [:]
        // coverage[frame][cluster] = seconds covered.
        var coverage = [[Double]](repeating: [], count: frameCount)
        for segment in segments {
            let cluster = segment.speakerId.rawValue
            let index: Int
            if let existing = clusterIndex[cluster] {
                index = existing
            } else {
                index = clusterIndex.count
                clusterIndex[cluster] = index
            }
            let first = max(0, Int(segment.startTime / frameDuration))
            let last = min(frameCount - 1, Int(segment.endTime / frameDuration))
            guard first <= last else { continue }
            for frame in first...last {
                let frameStart = Double(frame) * frameDuration
                let overlap =
                    min(segment.endTime, frameStart + frameDuration) - max(segment.startTime, frameStart)
                guard overlap > 0 else { continue }
                while coverage[frame].count <= index { coverage[frame].append(0) }
                coverage[frame][index] += overlap
            }
        }
        return coverage.map { row in
            guard let best = row.indices.max(by: { row[$0] < row[$1] }), row[best] > 0 else {
                return nil
            }
            return best
        }
    }

    /// Fraction of frame pairs — speech in *both* labelings — on which the
    /// two labelings agree about the same-speaker relation. Permutation
    /// invariant; 1.0 means identical partitions of the shared speech frames.
    static func coAssociationAgreement(_ a: [Int?], _ b: [Int?]) -> Double {
        // Frames that are speech in both runs.
        var frames: [(a: Int, b: Int)] = []
        for i in 0..<min(a.count, b.count) {
            if let la = a[i], let lb = b[i] { frames.append((la, lb)) }
        }
        guard frames.count >= 2 else { return 0 }
        // Count agreements via label-pair contingency instead of O(n²) pairs:
        // pairs same in both = Σ C(n_ab, 2); same in a = Σ C(n_a·, 2); etc.
        var joint: [Int: Double] = [:]
        var countA: [Int: Double] = [:]
        var countB: [Int: Double] = [:]
        for f in frames {
            joint[f.a &* 100_003 &+ f.b, default: 0] += 1
            countA[f.a, default: 0] += 1
            countB[f.b, default: 0] += 1
        }
        func choose2(_ n: Double) -> Double { n * (n - 1) / 2 }
        let total = choose2(Double(frames.count))
        let sameBoth = joint.values.reduce(0) { $0 + choose2($1) }
        let sameA = countA.values.reduce(0) { $0 + choose2($1) }
        let sameB = countB.values.reduce(0) { $0 + choose2($1) }
        // Agree = same in both + different in both.
        let agree = sameBoth + (total - sameA - sameB + sameBoth)
        return total > 0 ? agree / total : 0
    }
}

