import Domain
import FluidAudio
import Foundation
@testable import MLInfrastructure
import Testing

// MARK: - Helpers

/// Build a `ChunkEmbedding` whose embedding points in a given direction.
/// Directions are axis-aligned so cosine similarity between different axes
/// is exactly 0 and between equal axes exactly 1; blends give intermediate
/// values.
private func chunk(
    speaker: String,
    axis: Int,
    blend: (axis: Int, weight: Float)? = nil,
    start: Double = 0,
    duration: Double = 10
) -> ChunkEmbedding {
    var embedding = [Float](repeating: 0, count: 256)
    embedding[axis] = 1
    if let blend { embedding[blend.axis] = blend.weight }
    return ChunkEmbedding(
        speakerId: speaker,
        chunkIndex: 0,
        speakerIndex: 0,
        startTimeSeconds: start,
        endTimeSeconds: start + duration,
        embedding256: embedding
    )
}

// MARK: - Tests

struct OfflineDiarizationPluginTests {

    // MARK: Tuning defaults

    @Test("recommended tuning carries the measured destination-pipeline values")
    func recommendedTuning() {
        let tuning = OfflineDiarizationTuning.recommended
        #expect(tuning.clusteringThreshold == 0.85)
        #expect(tuning.segmentationStepRatio == 0.1)
        #expect(tuning.minSilenceToSplit == 0.15)
        #expect(tuning.centroidMergeThreshold == 0.6)
    }

    // MARK: Pass-2 centroid merging

    @Test("orthogonal clusters never merge")
    func orthogonalClustersDoNotMerge() {
        let chunks = [
            chunk(speaker: "S1", axis: 0),
            chunk(speaker: "S2", axis: 1),
        ]
        let merges = OfflineDiarizationPlugin.centroidMerges(chunks: chunks, threshold: 0.6)
        #expect(merges.isEmpty)
    }

    @Test("near-identical clusters merge, smaller duration into larger")
    func similarClustersMerge() {
        let chunks = [
            chunk(speaker: "S1", axis: 0, duration: 30),
            chunk(speaker: "S2", axis: 0, blend: (axis: 1, weight: 0.1), duration: 10),
        ]
        let merges = OfflineDiarizationPlugin.centroidMerges(chunks: chunks, threshold: 0.6)
        #expect(merges == ["S2": "S1"])
    }

    @Test("chained merges resolve transitively to the surviving label")
    func transitiveMergesResolve() {
        // S3 is closest to S2; S2 is closest to S1. After S3→S2 and S2→S1,
        // the mapping for S3 must point at S1, never at the dead S2.
        let chunks = [
            chunk(speaker: "S1", axis: 0, duration: 30),
            chunk(speaker: "S2", axis: 0, blend: (axis: 1, weight: 0.2), duration: 20),
            chunk(speaker: "S3", axis: 0, blend: (axis: 1, weight: 0.4), duration: 10),
        ]
        let merges = OfflineDiarizationPlugin.centroidMerges(chunks: chunks, threshold: 0.6)
        #expect(Set(merges.keys) == ["S2", "S3"])
        #expect(Set(merges.values) == ["S1"])
    }

    @Test("empty chunk list produces no merges")
    func emptyChunksNoMerges() {
        let merges = OfflineDiarizationPlugin.centroidMerges(chunks: [], threshold: 0.6)
        #expect(merges.isEmpty)
    }

    @Test("zero-duration and zero-vector chunks are ignored, not crashed on")
    func degenerateChunksIgnored() {
        let zeroVector = ChunkEmbedding(
            speakerId: "S9",
            chunkIndex: 0,
            speakerIndex: 0,
            startTimeSeconds: 0,
            endTimeSeconds: 5,
            embedding256: [Float](repeating: 0, count: 256)
        )
        let chunks = [
            chunk(speaker: "S1", axis: 0),
            chunk(speaker: "S2", axis: 0, duration: 0),
            zeroVector,
        ]
        let merges = OfflineDiarizationPlugin.centroidMerges(chunks: chunks, threshold: 0.6)
        #expect(merges.isEmpty)
    }

    // MARK: Merge application

    @Test("applyMerges relabels merged segments and leaves others untouched")
    func applyMergesRelabels() {
        let segments = [
            SpeakerSegment(speakerId: SpeakerID("S1"), startTime: 0, endTime: 5, confidence: 1),
            SpeakerSegment(speakerId: SpeakerID("S2"), startTime: 5, endTime: 9, confidence: 1),
        ]
        let relabeled = OfflineDiarizationPlugin.applyMerges(["S2": "S1"], to: segments)
        #expect(relabeled.map(\.speakerId.rawValue) == ["S1", "S1"])
        #expect(relabeled.map(\.startTime) == [0, 5])
        #expect(relabeled.map(\.endTime) == [5, 9])
    }

    // MARK: Engine surface

    @Test("plugin is not ready before prepare()")
    func notReadyBeforePrepare() async {
        let plugin = OfflineDiarizationPlugin()
        #expect(await plugin.isReady() == false)
    }

    @Test("diarize before prepare throws instead of crashing")
    func diarizeBeforePrepareThrows() async {
        let plugin = OfflineDiarizationPlugin()
        await #expect(throws: (any Error).self) {
            _ = try await plugin.diarize(samples: [Float](repeating: 0, count: 16_000), sampleRate: 16_000)
        }
    }
}

