import FluidAudio
import Foundation

/// Multipass offline diarization: run FluidAudio's `OfflineDiarizerManager`
/// (VBx clustering) several times and return the *consensus medoid* run.
///
/// Why: VBx clustering is initialization-sensitive. On meeting-15min with
/// fixed 4 speakers it is bimodal — ~60% of runs land at ~85% purity and
/// ~40% collapse two same-gender speakers (~68% purity). A single run is a
/// coin flip; the medoid of K runs is the majority mode.
///
/// Medoid selection is label-permutation-invariant: two runs are compared by
/// how often they agree that a pair of speech frames belongs to the same
/// speaker (co-association agreement), never by cluster names.
enum MultipassError: Error {
    case noRuns
}

struct MultipassDiarizer {
    /// Seconds per consensus frame. 0.5 s keeps the pairwise comparison
    /// cheap (~1.6M frame pairs for 15 min) while being much finer than
    /// typical turn lengths.
    static let frameDuration = 0.5

    struct RunOutcome {
        let index: Int
        let segments: [SpeakerSegment]
        /// Mean pairwise co-association agreement with every other run (0…1).
        var consensus: Double
        let clusterCount: Int
    }

    struct Result {
        let segments: [SpeakerSegment]
        let runs: [RunOutcome]
        let medoidIndex: Int
        /// Cluster relabelings applied by the centroid-merge pass
        /// (old label → surviving label). Empty when merging is disabled or
        /// nothing merged.
        let merges: [String: String]
    }

    /// Run `restarts` independent VBx passes over `samples` and return the
    /// medoid run's segments. The manager (and its loaded models) is reused
    /// across passes; only clustering initialization varies run-to-run.
    static func diarize(
        samples: [Float],
        config: OfflineDiarizerConfig,
        restarts: Int,
        mergeThreshold: Double? = nil,
        progress: (String) -> Void = { _ in }
    ) async throws -> Result {
        precondition(restarts >= 1, "need at least one restart")

        var config = config
        if mergeThreshold != nil { config.exposeChunkEmbeddings = true }
        let manager = OfflineDiarizerManager(config: config)
        try await manager.prepareModels()

        var allSegments: [[SpeakerSegment]] = []
        var allChunkEmbeddings: [[ChunkEmbedding]] = []
        for runIndex in 0..<restarts {
            let result = try await manager.process(audio: samples)
            let segments = result.segments.map { seg in
                SpeakerSegment(
                    speakerId: SpeakerID(seg.speakerId),
                    startTime: TimeInterval(seg.startTimeSeconds),
                    endTime: TimeInterval(seg.endTimeSeconds),
                    confidence: Double(seg.qualityScore)
                )
            }
            allSegments.append(segments)
            allChunkEmbeddings.append(result.chunkEmbeddings ?? [])
            let clusters = Set(segments.map(\.speakerId)).count
            progress("pass \(runIndex + 1)/\(restarts): \(segments.count) segments, \(clusters) clusters")
        }

        let duration = Double(samples.count) / 16_000.0
        let labelings = allSegments.map { frameLabels(segments: $0, duration: duration) }

        // Mean pairwise agreement of each run with all others.
        var outcomes: [RunOutcome] = allSegments.enumerated().map { index, segments in
            RunOutcome(
                index: index,
                segments: segments,
                consensus: 1.0,
                clusterCount: Set(segments.map(\.speakerId)).count
            )
        }
        if restarts > 1 {
            var pairAgreement = [[Double]](
                repeating: [Double](repeating: 1.0, count: restarts), count: restarts
            )
            for a in 0..<restarts {
                for b in (a + 1)..<restarts {
                    let agreement = coAssociationAgreement(labelings[a], labelings[b])
                    pairAgreement[a][b] = agreement
                    pairAgreement[b][a] = agreement
                }
            }
            for a in 0..<restarts {
                let others = (0..<restarts).filter { $0 != a }.map { pairAgreement[a][$0] }
                outcomes[a].consensus = others.reduce(0, +) / Double(others.count)
            }
        }

        guard
            let medoid = outcomes.max(by: { lhs, rhs in
                (lhs.consensus, -Double(lhs.index)) < (rhs.consensus, -Double(rhs.index))
            })
        else {
            throw MultipassError.noRuns
        }

        // Pass 2: centroid-based cluster merging on the medoid run.
        var segments = medoid.segments
        var merges: [String: String] = [:]
        if let mergeThreshold {
            merges = centroidMerges(
                chunks: allChunkEmbeddings[medoid.index], threshold: mergeThreshold
            )
            segments = applyMerges(merges, to: segments)
            for (from, to) in merges.sorted(by: { $0.key < $1.key }) {
                progress("pass 2 merge: \(from) → \(to)")
            }
        }

        return Result(
            segments: segments, runs: outcomes, medoidIndex: medoid.index, merges: merges
        )
    }

    /// Relabel segments whose cluster was merged away by pass 2.
    private static func applyMerges(
        _ merges: [String: String], to segments: [SpeakerSegment]
    ) -> [SpeakerSegment] {
        guard !merges.isEmpty else { return segments }
        return segments.map { seg in
            guard let target = merges[seg.speakerId.rawValue] else { return seg }
            return SpeakerSegment(
                speakerId: SpeakerID(target),
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }
    }

    // MARK: - Pass 2: centroid cluster merging

    /// Compute duration-weighted L2-normalized centroids per cluster from the
    /// exposed chunk embeddings, then greedily merge the most-similar cluster
    /// pair while its cosine similarity exceeds `threshold`. Smaller total
    /// duration merges into larger. Returns old→surviving label mapping
    /// (transitively resolved).
    static func centroidMerges(
        chunks: [ChunkEmbedding], threshold: Double
    ) -> [String: String] {
        // Accumulate duration-weighted sums of normalized embeddings.
        var sums: [String: [Double]] = [:]
        var durations: [String: Double] = [:]
        for chunk in chunks {
            let duration = max(0, chunk.endTimeSeconds - chunk.startTimeSeconds)
            guard duration > 0, !chunk.embedding256.isEmpty else { continue }
            let norm = sqrt(chunk.embedding256.reduce(0.0) { $0 + Double($1) * Double($1) })
            guard norm > 0 else { continue }
            var sum = sums[chunk.speakerId] ?? [Double](repeating: 0, count: chunk.embedding256.count)
            for i in 0..<chunk.embedding256.count {
                sum[i] += Double(chunk.embedding256[i]) / norm * duration
            }
            sums[chunk.speakerId] = sum
            durations[chunk.speakerId, default: 0] += duration
        }

        var merges: [String: String] = [:]
        var active = Set(sums.keys)
        while active.count > 1 {
            guard let pair = closestPair(active: active, sums: sums, durations: durations, threshold: threshold),
                let fromSum = sums[pair.from], var toSum = sums[pair.to]
            else { break }
            // Fold the merged cluster's weighted sum and duration into the survivor.
            for i in 0..<min(fromSum.count, toSum.count) { toSum[i] += fromSum[i] }
            sums[pair.to] = toSum
            durations[pair.to, default: 0] += durations[pair.from, default: 0]
            sums[pair.from] = nil
            active.remove(pair.from)
            // Redirect earlier merges that pointed at the disappearing label.
            for (key, value) in merges where value == pair.from { merges[key] = pair.to }
            merges[pair.from] = pair.to
        }
        return merges
    }

    /// Most-similar active cluster pair at or above `threshold`, oriented so
    /// the smaller total duration merges into the larger. `nil` when no pair
    /// clears the threshold.
    private static func closestPair(
        active: Set<String>,
        sums: [String: [Double]],
        durations: [String: Double],
        threshold: Double
    ) -> (from: String, to: String)? {
        var bestPair: (from: String, to: String)?
        var bestSim = threshold
        let ordered = active.sorted()
        for (i, a) in ordered.enumerated() {
            guard let sumA = sums[a] else { continue }
            for b in ordered.dropFirst(i + 1) {
                guard let sumB = sums[b] else { continue }
                let sim = cosine(sumA, sumB)
                if sim >= bestSim {
                    bestSim = sim
                    bestPair =
                        durations[a, default: 0] < durations[b, default: 0]
                        ? (from: a, to: b) : (from: b, to: a)
                }
            }
        }
        return bestPair
    }

    private static func cosine(_ a: [Double], _ b: [Double]) -> Double {
        var dot = 0.0
        var normA = 0.0
        var normB = 0.0
        for i in 0..<min(a.count, b.count) {
            dot += a[i] * b[i]
            normA += a[i] * a[i]
            normB += b[i] * b[i]
        }
        let denominator = sqrt(normA) * sqrt(normB)
        return denominator > 0 ? dot / denominator : 0
    }

    // MARK: - Frame consensus

    /// Discretize a segmentation into per-frame cluster indices. `nil` means
    /// no speech in that frame. When segments overlap a frame, the one
    /// covering more of it wins.
    static func frameLabels(segments: [SpeakerSegment], duration: Double) -> [Int?] {
        let frameCount = max(1, Int((duration / frameDuration).rounded(.up)))
        var clusterIndex: [String: Int] = [:]
        // coverage[frame][cluster] = seconds covered.
        var coverage = [[Double]](repeating: [], count: frameCount)
        for segment in segments {
            let cluster = segment.speakerId.rawValue
            let index: Int
            if let existing = clusterIndex[cluster] {
                index = existing
            } else {
                index = clusterIndex.count
                clusterIndex[cluster] = index
            }
            let first = max(0, Int(segment.startTime / frameDuration))
            let last = min(frameCount - 1, Int(segment.endTime / frameDuration))
            guard first <= last else { continue }
            for frame in first...last {
                let frameStart = Double(frame) * frameDuration
                let overlap =
                    min(segment.endTime, frameStart + frameDuration) - max(segment.startTime, frameStart)
                guard overlap > 0 else { continue }
                while coverage[frame].count <= index { coverage[frame].append(0) }
                coverage[frame][index] += overlap
            }
        }
        return coverage.map { row in
            guard let best = row.indices.max(by: { row[$0] < row[$1] }), row[best] > 0 else {
                return nil
            }
            return best
        }
    }

    /// Fraction of frame pairs — speech in *both* labelings — on which the
    /// two labelings agree about the same-speaker relation. Permutation
    /// invariant; 1.0 means identical partitions of the shared speech frames.
    static func coAssociationAgreement(_ a: [Int?], _ b: [Int?]) -> Double {
        // Frames that are speech in both runs.
        var frames: [(a: Int, b: Int)] = []
        for i in 0..<min(a.count, b.count) {
            if let la = a[i], let lb = b[i] { frames.append((la, lb)) }
        }
        guard frames.count >= 2 else { return 0 }
        // Count agreements via label-pair contingency instead of O(n²) pairs:
        // pairs same in both = Σ C(n_ab, 2); same in a = Σ C(n_a·, 2); etc.
        var joint: [Int: Double] = [:]
        var countA: [Int: Double] = [:]
        var countB: [Int: Double] = [:]
        for f in frames {
            joint[f.a &* 100_003 &+ f.b, default: 0] += 1
            countA[f.a, default: 0] += 1
            countB[f.b, default: 0] += 1
        }
        func choose2(_ n: Double) -> Double { n * (n - 1) / 2 }
        let total = choose2(Double(frames.count))
        let sameBoth = joint.values.reduce(0) { $0 + choose2($1) }
        let sameA = countA.values.reduce(0) { $0 + choose2($1) }
        let sameB = countB.values.reduce(0) { $0 + choose2($1) }
        // Agree = same in both + different in both.
        let agree = sameBoth + (total - sameA - sameB + sameBoth)
        return total > 0 ? agree / total : 0
    }
}

import Domain
import FluidAudio
import Foundation

// MARK: - Per-reference-speaker breakdown

/// How well a single ground-truth speaker is captured by the prediction.
struct ReferenceSpeakerScore {
    let speaker: String
    /// Total ground-truth speech time for this speaker (seconds).
    let referenceTime: Double
    /// Predicted cluster with the largest overlap of this speaker.
    let bestCluster: String
    /// Fraction of `referenceTime` covered by `bestCluster` (0…1).
    let bestClusterCoverage: Double
    /// Number of distinct predicted clusters that each cover ≥10% of
    /// `referenceTime`. >1 means this speaker was split across clusters.
    let coveringClusterCount: Int
}

// MARK: - Aggregate score

/// Result of scoring a diarization prediction against RTTM ground truth.
struct DiarizationScore {
    /// Time-weighted aggregate cluster purity (0…1). See `compute` for the
    /// exact formula.
    let aggregatePurity: Double
    let predictedClusterCount: Int
    let referenceSpeakerCount: Int
    /// Frame-wise DER fraction (0…1) from FluidAudio's Hungarian-matched
    /// `DiarizationDER`, computed with no collar.
    let der: Double
    let perSpeaker: [ReferenceSpeakerScore]
    /// Hungarian `predictedCluster → referenceSpeaker` label mapping.
    let mapping: [String: String]

    // MARK: Computation

    /// Score `predicted` speaker segments against `reference` RTTM turns.
    ///
    /// **Aggregate time-weighted purity** — for each predicted cluster `c`,
    /// let `overlap(c, r)` be the total temporal overlap between `c`'s
    /// segments and reference speaker `r`'s turns. Let
    /// `total(c) = Σ_r overlap(c, r)` (the cluster's overlapped time) and
    /// `best(c) = max_r overlap(c, r)` (its majority reference speaker's
    /// overlap). Then
    ///
    ///     aggregatePurity = Σ_c best(c) / Σ_c total(c)
    ///
    /// which is the standard time-weighted mean of per-cluster purity
    /// `best(c) / total(c)`, weighting each cluster by its overlapped time.
    static func compute(
        predicted: [SpeakerSegment],
        reference: [RTTMTurn]
    ) -> DiarizationScore {
        let predictedByCluster = Dictionary(grouping: predicted, by: { $0.speakerId.rawValue })
        let referenceBySpeaker = Dictionary(grouping: reference, by: { $0.speaker })

        // overlap[cluster][refSpeaker] = total overlapped seconds.
        var overlap: [String: [String: Double]] = [:]
        for (cluster, segments) in predictedByCluster {
            var row: [String: Double] = [:]
            for (refSpeaker, turns) in referenceBySpeaker {
                var acc = 0.0
                for seg in segments {
                    for turn in turns {
                        acc += Self.overlapSeconds(
                            aStart: seg.startTime, aEnd: seg.endTime,
                            bStart: turn.start, bEnd: turn.end
                        )
                    }
                }
                if acc > 0 { row[refSpeaker] = acc }
            }
            overlap[cluster] = row
        }

        // Aggregate purity: Σ best(c) / Σ total(c).
        var sumBest = 0.0
        var sumTotal = 0.0
        for (_, row) in overlap {
            let total = row.values.reduce(0, +)
            let best = row.values.max() ?? 0
            sumBest += best
            sumTotal += total
        }
        let purity = sumTotal > 0 ? sumBest / sumTotal : 0

        // Per-reference-speaker breakdown.
        var perSpeaker: [ReferenceSpeakerScore] = []
        for (refSpeaker, turns) in referenceBySpeaker {
            let refTime = turns.reduce(0.0) { $0 + $1.duration }
            // overlap of each cluster with this reference speaker.
            var clusterOverlaps: [(cluster: String, seconds: Double)] = []
            for (cluster, row) in overlap {
                if let secs = row[refSpeaker], secs > 0 {
                    clusterOverlaps.append((cluster, secs))
                }
            }
            let best = clusterOverlaps.max(by: { $0.seconds < $1.seconds })
            let coverage = refTime > 0 ? (best?.seconds ?? 0) / refTime : 0
            let coveringCount = clusterOverlaps.filter {
                refTime > 0 && $0.seconds / refTime >= 0.10
            }.count
            perSpeaker.append(
                ReferenceSpeakerScore(
                    speaker: refSpeaker,
                    referenceTime: refTime,
                    bestCluster: best?.cluster ?? "—",
                    bestClusterCoverage: coverage,
                    coveringClusterCount: coveringCount
                )
            )
        }
        perSpeaker.sort { $0.speaker < $1.speaker }

        // DER via FluidAudio's Hungarian-matched scorer (no collar).
        let refSegs = reference.map {
            DERSpeakerSegment(speaker: $0.speaker, start: $0.start, end: $0.end)
        }
        let hypSegs = predicted.map {
            DERSpeakerSegment(speaker: $0.speakerId.rawValue, start: $0.startTime, end: $0.endTime)
        }
        let derResult = DiarizationDER.compute(ref: refSegs, hyp: hypSegs)

        return DiarizationScore(
            aggregatePurity: purity,
            predictedClusterCount: predictedByCluster.count,
            referenceSpeakerCount: referenceBySpeaker.count,
            der: derResult.der,
            perSpeaker: perSpeaker,
            mapping: derResult.mapping
        )
    }

    private static func overlapSeconds(
        aStart: Double, aEnd: Double, bStart: Double, bEnd: Double
    ) -> Double {
        max(0, min(aEnd, bEnd) - max(aStart, bStart))
    }

    // MARK: Reference overlap

    /// Total reference time (seconds) during which two or more speakers talk
    /// simultaneously. This time is structurally unreachable for any
    /// single-label diarization output — it bounds how far exclusive-segment
    /// pipelines can ever get on this recording (#308 item 1).
    static func referenceOverlapSeconds(reference: [RTTMTurn]) -> Double {
        // Sweep line over turn boundaries counting active speakers.
        var events: [(time: Double, delta: Int)] = []
        for turn in reference {
            events.append((turn.start, 1))
            events.append((turn.end, -1))
        }
        events.sort { $0.time < $1.time }
        var active = 0
        var overlap = 0.0
        var prev = 0.0
        for event in events {
            if active >= 2 { overlap += event.time - prev }
            active += event.delta
            prev = event.time
        }
        return overlap
    }

    // MARK: Oracle assignment

    /// Sentinel cluster label for predicted segments with zero reference
    /// overlap. These are pure false-alarm time: no relabeling can help them,
    /// and grouping them under one label keeps them out of every real
    /// speaker's cluster.
    static let oracleFalseAlarmLabel = "ORACLE-FA"

    /// Relabel each predicted segment with the reference speaker that
    /// temporally overlaps it most — the *oracle assignment*. Scoring the
    /// relabeled hypothesis gives the ceiling any clustering algorithm could
    /// reach on this exact segmentation: residual impurity/DER comes from
    /// segment boundaries, missed speech, false alarms, and overlapped
    /// speech, not from cluster assignment.
    static func oracleRelabel(
        predicted: [SpeakerSegment],
        reference: [RTTMTurn]
    ) -> [SpeakerSegment] {
        let referenceBySpeaker = Dictionary(grouping: reference, by: { $0.speaker })
        return predicted.map { seg in
            var bestSpeaker = oracleFalseAlarmLabel
            var bestSeconds = 0.0
            for (refSpeaker, turns) in referenceBySpeaker {
                var acc = 0.0
                for turn in turns {
                    acc += overlapSeconds(
                        aStart: seg.startTime, aEnd: seg.endTime,
                        bStart: turn.start, bEnd: turn.end
                    )
                }
                // Deterministic tie-break: larger overlap wins, then
                // lexicographically smaller speaker name.
                if acc > bestSeconds || (acc == bestSeconds && acc > 0 && refSpeaker < bestSpeaker) {
                    bestSeconds = acc
                    bestSpeaker = refSpeaker
                }
            }
            return SpeakerSegment(
                speakerId: SpeakerID(bestSpeaker),
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }
    }
}

// MARK: - Rendering

extension DiarizationScore {
    /// Print a compact scoring table to stdout using the shared `Term` styling.
    func printReport() {
        Term.header("DIARIZATION SCORE (vs RTTM)")
        Term.metric(
            "Aggregate purity",
            String(format: "%.1f%%", aggregatePurity * 100),
            color: aggregatePurity >= 0.85 ? Term.green : Term.yellow
        )
        Term.metric(
            "DER (no collar)",
            String(format: "%.1f%%", der * 100),
            color: der <= 0.30 ? Term.green : Term.yellow
        )
        Term.metric(
            "Clusters",
            "\(predictedClusterCount) predicted vs \(referenceSpeakerCount) reference",
            color: predictedClusterCount == referenceSpeakerCount ? Term.green : Term.yellow
        )

        Term.subheader("Per reference speaker")
        print("    \(Term.dim)\(pad("speaker", 11))  \(pad("ref(s)", 8))  \(pad("best-cluster", 14))  cover    #clusters≥10%\(Term.reset)")
        for s in perSpeaker {
            let color = s.coveringClusterCount > 1 ? Term.yellow : Term.green
            let speaker = pad(s.speaker, 11)
            let refTime = pad(String(format: "%.1f", s.referenceTime), 8)
            let cluster = pad(s.bestCluster, 14)
            let cover = pad(String(format: "%.1f%%", s.bestClusterCoverage * 100), 6)
            print("    \(color)\(speaker)\(Term.reset)  \(refTime)  \(cluster)  \(cover)   \(color)\(s.coveringClusterCount)\(Term.reset)")
        }
    }

    private func pad(_ s: String, _ width: Int) -> String {
        s.count >= width ? s : s + String(repeating: " ", count: width - s.count)
    }
}

