import Foundation
import OSLog
import Domain

/// Orchestrates a post-transcription diarization pass.
///
/// Loads stored audio for a recording, runs it through the diarization engine
/// to identify speaker boundaries, then merges those boundaries with the
/// transcription segments to produce a fully attributed ``DiarizedTranscript``.
///
/// Each ``TranscriptionSegment`` is assigned the speaker whose time range has
/// the maximum overlap with it. Segments that fall entirely outside all speaker
/// ranges are labelled `"Unknown"`.
///
/// All I/O is delegated to injected domain protocols — this actor contains no
/// direct file-system, audio-framework, or inference dependencies.
public actor DiarizeMeetingUseCase {

    // MARK: - Dependencies

    private let diarization: any DiarizationEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let writer: any DiarizationWriteRepository

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Diarization")

    // MARK: - Init

    public init(
        diarization: any DiarizationEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        writer: any DiarizationWriteRepository
    ) {
        self.diarization = diarization
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
    }

    // MARK: - Diarize

    /// Produces a diarized transcript by aligning speaker segments with
    /// transcription segments for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording.
    ///   - transcription: The transcription result to enrich with speaker labels.
    /// - Returns: A ``DiarizedTranscript`` where every segment carries a speaker
    ///   identity, or `"Unknown"` when no speaker segment overlaps it.
    /// - Throws: Any error produced by storage, sample loader, or diarization —
    ///   errors are never swallowed here.
    public func diarize(
        recordingId: RecordingID,
        transcription: TranscriptionResult,
    ) async throws -> DiarizedTranscript {
        logger.info("Starting diarization for \(recordingId.rawValue, privacy: .public)")

        let recording = try await reader.getRecording(id: recordingId)
        let audioURL = recording.metadata.audioURL
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .public)")

        let samples = try await sampleLoader.loadSamples(from: audioURL)
        // swiftlint:disable:next line_length
        logger.info("Loaded \(samples.count, privacy: .public) samples from \(audioURL.lastPathComponent, privacy: .public)")

        let startTime = CFAbsoluteTimeGetCurrent()
        let speakerSegments = try await runDiarization(samples: samples)
        let diarizedSegments = alignSegments(speakers: speakerSegments, transcription: transcription)
        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        let uniqueSpeakers = Set(speakerSegments.map(\.speakerId))
        // swiftlint:disable:next line_length
        logger.info("Merged \(diarizedSegments.count, privacy: .public) segments across \(uniqueSpeakers.count, privacy: .public) speakers in \(elapsed, format: .fixed(precision: 3), privacy: .public)s")

        let diarizedTranscript = DiarizedTranscript(
            segments: diarizedSegments,
            speakerCount: uniqueSpeakers.count,
            processingTime: elapsed,
        )

        try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
        logger.info("Saved \(diarizedTranscript.segments.count, privacy: .public) segments for \(recordingId, privacy: .private)")

        return diarizedTranscript
    }

    // MARK: - Helpers

    /// Prepares the diarization engine if needed and runs it on the given samples.
    private func runDiarization(samples: [Float]) async throws -> [SpeakerSegment] {
        if await !diarization.isReady() { try await diarization.prepare() }
        let segments = try await diarization.diarize(samples: samples, sampleRate: 16000)
        logger.info("Diarization engine returned \(segments.count, privacy: .public) speaker segments")
        for (i, seg) in segments.prefix(10).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  speaker[\(i, privacy: .public)]: id=\(seg.speakerId, privacy: .public) start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s")
        }
        return segments
    }

    /// Aligns transcription segments with speaker segments by maximum time overlap.
    private func alignSegments(
        speakers: [SpeakerSegment],
        transcription: TranscriptionResult,
    ) -> [DiarizedSegment] {
        // swiftlint:disable:next line_length
        logger.info("Merging \(speakers.count, privacy: .public) speaker segments × \(transcription.segments.count, privacy: .public) transcription segments")
        for (i, seg) in transcription.segments.prefix(5).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  transcript[\(i, privacy: .public)]: start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s text=\(String(seg.text.prefix(40)), privacy: .private)")
        }
        return transcription.segments.map { seg in
            let best = speakers
                .map { (speaker: $0, overlap: overlapDuration($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let speakerId: SpeakerID = if let b = best, b.overlap > 0 { b.speaker.speakerId } else { .unknown }
            return DiarizedSegment(
                text: seg.text,
                speakerId: speakerId,
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence,
            )
        }
    }

    nonisolated private func overlapDuration(
        _ speaker: SpeakerSegment,
        _ transcript: TranscriptionSegment,
    ) -> TimeInterval {
        max(0, min(speaker.endTime, transcript.endTime) - max(speaker.startTime, transcript.startTime))
    }
}

import Foundation

/// Assigns a unique animal codename to each speaker within a meeting.
///
/// - Deterministic: same speakerId + meetingId always produces the same animal.
/// - Per-meeting: different meetings produce different animal sets for the same speaker slot.
/// - Unique within a meeting: numeric-tail IDs (speaker-0…speaker-39) guaranteed
///   distinct. Non-numeric IDs use a hash fallback — collision-resistant, not guaranteed.
public enum SpeakerNamer {
    /// 40 animals — memorable, ≤2 syllables, tonally varied.
    private static let animals: [String] = [
        "FALCON", "OTTER", "LYNX", "CRANE", "IBIS",
        "SWIFT", "RAVEN", "BISON", "GECKO", "HERON",
        "KITE", "MINK", "QUAIL", "ROBIN", "STOAT",
        "TEAL", "WREN", "NEWT", "MOLE", "LARK",
        "FINCH", "DOVE", "COOT", "VOLE", "DACE",
        "KESTREL", "MERLIN", "CURLEW", "DUNLIN", "PLOVER",
        "AVOCET", "GANNET", "FULMAR", "PETREL", "GROUSE",
        "SNIPE", "DIPPER", "REDWING", "SISKIN", "LINNET",
    ]

    /// Returns a deterministic animal codename for a speaker in a given meeting.
    ///
    /// Algorithm: extract the speaker index from the ID tail (e.g. "speaker-2" → 2),
    /// derive a per-meeting rotation offset from `meetingId`, then index into the
    /// animal list. This guarantees speakers within the same meeting always get
    /// different animals, while the animals rotate between meetings.
    public static func name(speakerId: String, meetingId: String) -> String {
        let count = animals.count
        let idx = speakerIndex(from: speakerId)
        let offset = abs(SpeakerDisplay.deterministicHash(meetingId)) % count
        return animals[(offset + idx) % count]
    }

    /// Extracts the trailing integer from IDs like "speaker-0", "bob-2", "spk_1".
    /// Falls back to a hash of the full ID for non-numeric tails.
    private static func speakerIndex(from id: String) -> Int {
        let tail = id.split(separator: "-").last ?? id.split(separator: "_").last ?? Substring(id)
        if let n = Int(tail) { return n }
        return abs(SpeakerDisplay.deterministicHash(String(tail))) % animals.count
    }
}

import Domain
import Foundation

public struct TranscriptTurnDisplay: Identifiable, Equatable, Sendable {
    public let id: String
    public let timestamp: String
    public let speakerName: String
    public let channelLabel: String
    public let text: String
    public let isCurrent: Bool

    public static func from(_ segment: DiarizedSegment, isCurrent: Bool = false) -> Self {
        TranscriptTurnDisplay(
            id: "\(segment.speakerId.rawValue)-\(segment.startTime)",
            timestamp: formatTime(segment.startTime),
            speakerName: formatSpeaker(segment.speakerId.rawValue),
            channelLabel: "MIC",
            text: segment.text,
            isCurrent: isCurrent
        )
    }

    public static func from(
        _ segment: StreamingSegment,
        meetingId: RecordingID? = nil,
        isCurrent: Bool = false
    ) -> Self {
        let spk = segment.speakerId?.rawValue ?? "unknown"
        return TranscriptTurnDisplay(
            id: "\(spk)-\(segment.timestamp)",
            timestamp: formatTime(segment.timestamp),
            speakerName: meetingId.map {
                SpeakerNamer.name(speakerId: spk, meetingId: $0.rawValue)
            } ?? formatSpeaker(spk),
            channelLabel: segment.track == .microphone ? "MIC" : "SYS",
            text: segment.text,
            isCurrent: isCurrent
        )
    }
}

private func formatTime(_ seconds: TimeInterval) -> String {
    seconds.mmss
}

private func formatSpeaker(_ speakerId: String) -> String {
    let parts = speakerId.split(separator: "-")
    if parts.count >= 2, let last = parts.last {
        return "SPEAKER \(last)".uppercased()
    }
    return speakerId.uppercased()
}

import Foundation
import Logging
import Domain
import Business
import AudioInfrastructure
import MLInfrastructure
import StorageInfrastructure
import Presentation

/// Builds the transcription, diarization, summarization, and export stack.
///
/// Pure struct with no stored state — call `build(storage:audioCapture:config:)` once per assembly.
@MainActor
struct TranscriptionSubAssembler {
    private let logger = AppLogger.for(category: "TranscriptionSubAssembler")
    struct Built {
        let stopUseCase: StopAndTranscribeUseCase
        let cleanupUseCase: CleanupTranscriptionUseCase
        let diarizeUseCase: DiarizeMeetingUseCase
        let summarizeUseCase: SummarizeMeetingUseCase
        let exportUseCase: ExportAudioUseCase
        let streamingUseCase: StreamingTranscriptionUseCase
        let liveTranscriptionVM: LiveTranscriptionViewModel
        let liveTranslateUseCase: LiveTranslateUseCase
        /// The primary transcription engine; passed to PipelineCoordinator for memory-gate unload.
        let primaryEngine: any TranscriptionEngine
        /// The summarization engine; shared with RepairTranscriptUseCase to avoid duplicate model loads.
        let summarizationEngine: any SummarizationEngine
        /// Stored handle for the background prewarm task.
        /// AppAssembler holds Built for the app lifetime, so this task can be
        /// cancelled on teardown by calling prewarmTask.cancel().
        let prewarmTask: Task<Void, Never>
        /// Connects a delegate to receive model-download progress from every
        /// download-capable engine in this stack (primary + cleanup). Wired by
        /// AppAssemblerBuilders.buildMenuBarVM once MenuBarViewModel exists,
        /// since MenuBarViewModel is constructed after Built (#212).
        let connectDownloadDelegate: @Sendable (any ModelDownloadDelegate) async -> Void
    }

    private func createPrewarmTask(
        summarizeUseCase: SummarizeMeetingUseCase,
        primaryEngine: any TranscriptionEngine,
    ) -> Task<Void, Never> {
        let logger = self.logger
        return Task.detached(priority: .background) {
            do {
                try await summarizeUseCase.prewarm()
            } catch {
                logger.warning("Summarization prewarm failed (non-fatal): \(error, privacy: .private)")
            }
            do {
                try await primaryEngine.loadModel(ModelIDs.parakeetPrimary)
            } catch {
                logger.warning("Primary model pre-load failed (non-fatal): \(error, privacy: .private)")
            }
        }
    }

    func build(
        storage: GRDBStorageActor,
        audioCapture: CoreAudioTapCaptureActor,
        config: AppConfig,
    ) -> Built {
        let telemetry = InferenceTelemetry()
        // Keep concrete references (not yet erased to `any TranscriptionEngine`) so
        // connectDownloadDelegate can call each plugin's own setDownloadDelegate — that
        // setter isn't part of the TranscriptionEngine protocol (#212).
        let parakeetPrimary: ParakeetPlugin?
        let whisperKitPrimary: WhisperKitPlugin?
        let primaryEngine: any TranscriptionEngine
        switch config.transcription.defaultEngine {
        case .parakeet:
            let plugin = ParakeetPlugin()
            parakeetPrimary = plugin
            whisperKitPrimary = nil
            primaryEngine = plugin
        case .whisperkit:
            let plugin = WhisperKitPlugin()
            parakeetPrimary = nil
            whisperKitPrimary = plugin
            primaryEngine = plugin
        }
        let cleanupEngine = WhisperKitPlugin()
        let sampleLoader = AudioFileLoader()
        let diarization = OfflineDiarizationPlugin()
        let summarizationEngine: any SummarizationEngine = MLXSummarizationPlugin()
        let summarizeUseCase = SummarizeMeetingUseCase(
            summarization: summarizationEngine,
            config: config.summarization,
            storage: storage,
        )
        let prewarmTask = createPrewarmTask(summarizeUseCase: summarizeUseCase, primaryEngine: primaryEngine)
        return Built(
            stopUseCase: StopAndTranscribeUseCase(
                audioCapture: audioCapture, transcription: primaryEngine,
                storage: storage, sampleLoader: sampleLoader,
                modelId: ModelIDs.parakeetPrimary, telemetry: telemetry,
            ),
            cleanupUseCase: CleanupTranscriptionUseCase(
                transcription: cleanupEngine, sampleLoader: sampleLoader,
                reader: storage, transcriptReader: storage, writer: storage, telemetry: telemetry,
            ),
            diarizeUseCase: DiarizeMeetingUseCase(
                diarization: diarization, sampleLoader: sampleLoader, reader: storage, writer: storage,
            ),
            summarizeUseCase: summarizeUseCase,
            exportUseCase: ExportAudioUseCase(storage: storage, exportEngine: AVFoundationExporter()),
            streamingUseCase: StreamingTranscriptionUseCase(transcription: primaryEngine),
            liveTranscriptionVM: LiveTranscriptionViewModel(),
            liveTranslateUseCase: LiveTranslateUseCase(translation: AppleTranslationPlugin()),
            primaryEngine: primaryEngine,
            summarizationEngine: summarizationEngine,
            prewarmTask: prewarmTask,
            connectDownloadDelegate: { delegate in
                await parakeetPrimary?.setDownloadDelegate(delegate)
                await whisperKitPrimary?.setDownloadDelegate(delegate)
                await cleanupEngine.setDownloadDelegate(delegate)
            },
        )
    }
}

