95	    private static func computePowerSpectrum(_ frame: Span<Float>) -> [Float] {
96	        let log2n = vDSP_Length(log2(Float(fftSize)))
97	        guard let setup = Self.fftSetupBox?.setup else {
98	            return [Float](repeating: 0, count: fftSize / 2)
99	        }
100	
101	        var realPart = [Float](repeating: 0, count: fftSize / 2)
102	        var imagPart = [Float](repeating: 0, count: fftSize / 2)
103	        // #279: the windowed frame lives in a 2 KB stack scratch buffer
104	        // instead of two heap arrays per frame (`var windowed = frame` copy
105	        // plus a per-frame Hann recompute — see the cached hannWindow above).
106	        withUnsafeTemporaryAllocation(of: Float.self, capacity: fftSize) { windowed in
107	            frame.withUnsafeBufferPointer { framePtr in
108	                vDSP_vmul(framePtr.baseAddress!, 1, hannWindow, 1, windowed.baseAddress!, 1, vDSP_Length(fftSize))
109	            }
110	            realPart.withUnsafeMutableBufferPointer { realBuf in
111	                imagPart.withUnsafeMutableBufferPointer { imagBuf in
112	                    var splitComplex = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
