115	                        vDSP_fft_zrip(setup, &splitComplex, 1, log2n, FFTDirection(kFFTDirection_Forward))
116	                    }
117	                }
118	            }
119	        }
120	
121	        var power = [Float](repeating: 0, count: fftSize / 2)
122	        realPart.withUnsafeMutableBufferPointer { realBuf in
123	            imagPart.withUnsafeMutableBufferPointer { imagBuf in
124	                var split = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
125	                vDSP_zvmags(&split, 1, &power, 1, vDSP_Length(fftSize / 2))
126	            }
127	        }
128	        return power
129	    }
