131	    private static func applyMelFilterbank(_ power: [Float]) -> [Float] {
132	        let nBins = power.count
133	        var mel = [Float](repeating: 0, count: numMelBands)
134	        let binsPerBand = max(1, nBins / numMelBands)
135	        // #279: sum bands directly from the power buffer — the old
136	        // Array(power[start ..< end]) allocated 40 small arrays per frame.
137	        power.withUnsafeBufferPointer { buf in
138	            for band in 0 ..< numMelBands {
