154	        var variance = [Float](repeating: 0, count: numMelBands)
155	
156	        for frame in frames {
157	            for i in 0 ..< min(frame.count, numMelBands) {
158	                avg[i] += frame[i]
159	            }
160	        }
161	        var count = Float(frames.count)
162	        vDSP_vsdiv(avg, 1, &count, &avg, 1, vDSP_Length(numMelBands))
163	
164	        for frame in frames {
165	            for i in 0 ..< min(frame.count, numMelBands) {
166	                let diff = frame[i] - avg[i]
167	                variance[i] += diff * diff
168	            }
169	        }
170	        vDSP_vsdiv(variance, 1, &count, &variance, 1, vDSP_Length(numMelBands))
171	
172	        var embedding = avg + variance
173	        if embedding.count < embeddingDim {
174	            embedding += [Float](repeating: 0, count: embeddingDim - embedding.count)
175	        } else if embedding.count > embeddingDim {
176	            embedding = Array(embedding.prefix(embeddingDim))
177	        }
178	
179	        var norm: Float = 0
180	        vDSP_svesq(embedding, 1, &norm, vDSP_Length(embeddingDim))
181	        norm = sqrt(norm)
182	        if norm > 0 {
183	            vDSP_vsdiv(embedding, 1, &norm, &embedding, 1, vDSP_Length(embeddingDim))
184	        }
185	
186	        return embedding
187	    }
