import Accelerate
import Domain
import Foundation
import Logging

public struct VoiceEmbeddingActor: VoiceEmbeddingEngine, Sendable {
    public init() {}

    public func extract(from samples: [Float]) async -> [Float] {
        await Task.detached(priority: .userInitiated) {
            VoiceEmbedding.extract(from: samples)
        }.value
    }

    public func cosineSimilarity(_ a: [Float], _ b: [Float]) async -> Float {
        await Task.detached(priority: .userInitiated) {
            VoiceEmbedding.cosineSimilarity(a, b)
        }.value
    }
}

public enum VoiceEmbedding {
    private static let logger = AppLogger.for(category: "VoiceEmbedding")
    private static let embeddingDim = 64
    private static let fftSize = 512
    private static let hopSize = 256
    private static let numMelBands = 40
    private static let sampleRate: Float = 16000
    /// Wraps the C FFT setup so vDSP_destroy_fftsetup is called deterministically at process exit.
    private final class FFTSetupBox {
        let setup: OpaquePointer
        init?(_ log2n: vDSP_Length) {
            guard let s = vDSP_create_fftsetup(log2n, FFTRadix(kFFTRadix2)) else { return nil }
            setup = s
        }

        deinit { vDSP_destroy_fftsetup(setup) }
    }

    // Safety: created once at process load time, then only read concurrently.
    private nonisolated(unsafe) static let fftSetupBox: FFTSetupBox? = FFTSetupBox(vDSP_Length(9))

    /// #279: Hann window computed once instead of per frame (was recomputed
    /// up to 200 times per extract call).
    private static let hannWindow: [Float] = {
        var window = [Float](repeating: 0, count: fftSize)
        vDSP_hann_window(&window, vDSP_Length(fftSize), Int32(vDSP_HANN_NORM))
        return window
    }()

    public static func extract(from samples: [Float]) -> [Float] {
        guard samples.count >= fftSize else {
            return [Float](repeating: 0, count: embeddingDim)
        }

        let melEnergies = computeMelSpectrogram(samples)
        return averageAndProject(melEnergies)
    }

    public static func cosineSimilarity(_ a: [Float], _ b: [Float]) -> Float {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot: Float = 0, normA: Float = 0, normB: Float = 0
        vDSP_dotpr(a, 1, b, 1, &dot, vDSP_Length(a.count))
        vDSP_svesq(a, 1, &normA, vDSP_Length(a.count))
        vDSP_svesq(b, 1, &normB, vDSP_Length(b.count))
        let denom = sqrt(normA) * sqrt(normB)
        guard denom > 0 else { return 0 }
        return dot / denom
    }

    private static func computeMelSpectrogram(_ samples: [Float]) -> [[Float]] {
        let numFrames = (samples.count - fftSize) / hopSize + 1
        guard numFrames > 0 else { return [] }

        var frames: [[Float]] = []
        frames.reserveCapacity(min(numFrames, 200))
        // #279: frames are zero-copy sub-spans of the input instead of a
        // fresh 2 KB [Float] per frame (up to 200 per extract call).
        // `Array.span` is macOS 26-gated, so the span comes from the buffer
        // pointer (SE-0447); it never escapes this closure.
        samples.withUnsafeBufferPointer { buf in
            let span = Span(_unsafeElements: buf)
            for i in 0 ..< min(numFrames, 200) {
                let start = i * hopSize
                let end = start + fftSize
                guard end <= span.count else { break }
                let power = computePowerSpectrum(span.extracting(start ..< end))
                let mel = applyMelFilterbank(power)
                frames.append(mel)
            }
        }
        return frames
    }

    private static func computePowerSpectrum(_ frame: Span<Float>) -> [Float] {
        let log2n = vDSP_Length(log2(Float(fftSize)))
        guard let setup = Self.fftSetupBox?.setup else {
            return [Float](repeating: 0, count: fftSize / 2)
        }

        var realPart = [Float](repeating: 0, count: fftSize / 2)
        var imagPart = [Float](repeating: 0, count: fftSize / 2)
        // #279: the windowed frame lives in a 2 KB stack scratch buffer
        // instead of two heap arrays per frame (`var windowed = frame` copy
        // plus a per-frame Hann recompute — see the cached hannWindow above).
        withUnsafeTemporaryAllocation(of: Float.self, capacity: fftSize) { windowed in
            frame.withUnsafeBufferPointer { framePtr in
                vDSP_vmul(framePtr.baseAddress!, 1, hannWindow, 1, windowed.baseAddress!, 1, vDSP_Length(fftSize))
            }
            realPart.withUnsafeMutableBufferPointer { realBuf in
                imagPart.withUnsafeMutableBufferPointer { imagBuf in
                    var splitComplex = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
                    windowed.baseAddress!.withMemoryRebound(to: DSPComplex.self, capacity: fftSize / 2) { complexPtr in
                        vDSP_ctoz(complexPtr, 2, &splitComplex, 1, vDSP_Length(fftSize / 2))
                        vDSP_fft_zrip(setup, &splitComplex, 1, log2n, FFTDirection(kFFTDirection_Forward))
                    }
                }
            }
        }

        var power = [Float](repeating: 0, count: fftSize / 2)
        realPart.withUnsafeMutableBufferPointer { realBuf in
            imagPart.withUnsafeMutableBufferPointer { imagBuf in
                var split = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
                vDSP_zvmags(&split, 1, &power, 1, vDSP_Length(fftSize / 2))
            }
        }
        return power
    }

    private static func applyMelFilterbank(_ power: [Float]) -> [Float] {
        let nBins = power.count
        var mel = [Float](repeating: 0, count: numMelBands)
        let binsPerBand = max(1, nBins / numMelBands)
        // #279: sum bands directly from the power buffer — the old
        // Array(power[start ..< end]) allocated 40 small arrays per frame.
        power.withUnsafeBufferPointer { buf in
            for band in 0 ..< numMelBands {
                let start = band * binsPerBand
                let end = min(start + binsPerBand, nBins)
                guard start < end else { continue }
                var sum: Float = 0
                vDSP_sve(buf.baseAddress! + start, 1, &sum, vDSP_Length(end - start))
                mel[band] = log(max(sum, 1e-10))
            }
        }
        return mel
    }

    private static func averageAndProject(_ frames: [[Float]]) -> [Float] {
        guard !frames.isEmpty else { return [Float](repeating: 0, count: embeddingDim) }

        var avg = [Float](repeating: 0, count: numMelBands)
        var variance = [Float](repeating: 0, count: numMelBands)

        for frame in frames {
            for i in 0 ..< min(frame.count, numMelBands) {
                avg[i] += frame[i]
            }
        }
        var count = Float(frames.count)
        vDSP_vsdiv(avg, 1, &count, &avg, 1, vDSP_Length(numMelBands))

        for frame in frames {
            for i in 0 ..< min(frame.count, numMelBands) {
                let diff = frame[i] - avg[i]
                variance[i] += diff * diff
            }
        }
        vDSP_vsdiv(variance, 1, &count, &variance, 1, vDSP_Length(numMelBands))

        var embedding = avg + variance
        if embedding.count < embeddingDim {
            embedding += [Float](repeating: 0, count: embeddingDim - embedding.count)
        } else if embedding.count > embeddingDim {
            embedding = Array(embedding.prefix(embeddingDim))
        }

        var norm: Float = 0
        vDSP_svesq(embedding, 1, &norm, vDSP_Length(embeddingDim))
        norm = sqrt(norm)
        if norm > 0 {
            vDSP_vsdiv(embedding, 1, &norm, &embedding, 1, vDSP_Length(embeddingDim))
        }

        return embedding
    }
}

import Domain
import Logging
import SwiftUI

// MARK: - TranscriptTabView
//
// Speaker-attributed, word-tappable transcript display with audio playback.
//
// Design choice: AudioPlayerViewModel is passed as a parameter (not created internally)
// so the caller controls the driver (Infrastructure), preserving the strict layer rule
// that Presentation never imports Infrastructure. The owner creates the VM and passes it.
//
// INV-007: View is never blank — shows speaker turns OR flat-text fallback (COMPAT-004).
// OBS-005: Word tap logged at DEBUG: recording_id (privacy: .private), word_index, seek_time.

@MainActor
public struct TranscriptTabView: View {
    @Bindable public var viewModel: MeetingDetailViewModel
    public var audioPlayerViewModel: AudioPlayerViewModel

    private let logger = AppLogger.for(category: "TranscriptTab")

    public init(viewModel: MeetingDetailViewModel, audioPlayerViewModel: AudioPlayerViewModel) {
        self.viewModel = viewModel
        self.audioPlayerViewModel = audioPlayerViewModel
    }

    // MARK: - Derived state

    private var activeLocation: ActiveWordLocation? {
        TranscriptTabViewHelpers.activeLocation(
            in: viewModel.segments,
            at: audioPlayerViewModel.currentTime
        )
    }

    // MARK: - Body

    public var body: some View {
        VStack(spacing: 0) {
            if viewModel.segments.isEmpty {
                // COMPAT-004: no diarized segments — fall back to flat transcript text.
                ScrollView {
                    VStack(alignment: .leading) {
                        if let transcript = viewModel.transcript, !transcript.isEmpty {
                            Text(transcript)
                                .font(.body)
                                .textSelection(.enabled)
                                .frame(maxWidth: .infinity, alignment: .leading)
                        } else {
                            Text("No transcript available")
                                .font(.body)
                                .foregroundStyle(.secondary)
                                .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
            } else {
                // Compute the O(n) active-word scan once per body evaluation and
                // derive the active segment id from its result — the body runs on
                // every 30 fps playback tick, so a second scan is pure waste.
                let location = activeLocation
                TranscriptSpeakerScrollView(
                    segments: viewModel.segments,
                    activeLocation: location,
                    activeSegmentID: TranscriptTabViewHelpers.segmentID(for: location, in: viewModel.segments),
                    onWordTap: handleWordTap
                )
            }
            Divider()
            AudioPlayerBar(viewModel: audioPlayerViewModel)
        }
        .onChange(of: viewModel.selectedMeeting?.id) { _, _ in
            // OBS-005 / SAFE-005: load audio for the newly selected meeting.
            // loadGracefully swallows errors and logs at ERROR (ORD-003).
            if let url = viewModel.audioURL {
                audioPlayerViewModel.loadGracefully(url: url)
            }
        }
    }

    // MARK: - Word tap

    private func handleWordTap(segment: DiarizedSegment, segmentIndex: Int, wordIndex: Int) {
        let seekTime: TimeInterval
        if let wordTimings = segment.wordTimings, wordIndex < wordTimings.count {
            seekTime = wordTimings[wordIndex].startTime
        } else {
            seekTime = segment.startTime
        }
        let recordingID = viewModel.selectedMeeting?.id.rawValue ?? "unknown"
        logger.debug(
            "word tap — recording_id=\(recordingID, privacy: .private) word_index=\(wordIndex, privacy: .public) seek_time=\(seekTime, privacy: .public)"
        )
        audioPlayerViewModel.seek(to: seekTime)
    }
}

import Foundation

/// A transcribed segment attributed to a single speaker.
///
/// Combines the spoken text from a transcription pass with the speaker
/// identity and time boundaries from the diarization pipeline.
public struct DiarizedSegment: Sendable, Identifiable {
    public var id: String {
        "\(speakerId)-\(startTime)"
    }

    /// The transcribed text for this segment.
    public let text: String

    /// Stable identifier for the attributed speaker (e.g. "speaker-0").
    public let speakerId: SpeakerID

    /// Start time of the segment relative to the audio stream origin, in seconds.
    public let startTime: TimeInterval

    /// End time of the segment relative to the audio stream origin, in seconds.
    public let endTime: TimeInterval

    /// Combined diarization and transcription confidence in the range [0, 1].
    public let confidence: Double

    /// Word-level timing information for each word in this segment.
    ///
    /// `nil` when the transcription engine did not produce word-level timestamps.
    public let wordTimings: [WordTimestamp]?

    public init(
        text: String,
        speakerId: SpeakerID,
        startTime: TimeInterval,
        endTime: TimeInterval,
        confidence: Double,
        wordTimings: [WordTimestamp]? = nil
    ) {
        self.text = text
        self.speakerId = speakerId
        self.startTime = startTime
        self.endTime = endTime
        self.confidence = confidence
        self.wordTimings = wordTimings
    }
}

/// The complete diarized transcript for a single recording.
///
/// Aggregates all ``DiarizedSegment`` values produced by aligning the
/// transcription output with the diarization pipeline, along with summary
/// metadata about the run.
public struct DiarizedTranscript: Sendable {
    /// Ordered segments that make up this transcript, each attributed to a speaker.
    public let segments: [DiarizedSegment]

    /// Number of distinct speakers identified in this transcript.
    public let speakerCount: Int

    /// Wall-clock time in seconds taken to produce the diarized transcript.
    public let processingTime: TimeInterval

    public init(
        segments: [DiarizedSegment],
        speakerCount: Int,
        processingTime: TimeInterval
    ) {
        self.segments = segments
        self.speakerCount = speakerCount
        self.processingTime = processingTime
    }
}

