import Domain
import SwiftUI

// MARK: - TranscriptSpeakerScrollView
//
// The speaker-turn scroll area extracted from TranscriptTabView to satisfy the
// 150-line file-size limit. Renders one SpeakerTurnView per DiarizedSegment and
// auto-scrolls to keep the active segment visible during playback.
//
// Scroll sync (OBS-005-scroll): `onChange(of: activeSegmentID)` fires whenever
// the active playback location crosses a segment boundary. The animated scroll
// targets `.center` anchor so the active turn stays readable without jumping to
// the top or bottom of the viewport.

@MainActor
struct TranscriptSpeakerScrollView: View {
    let segments: [DiarizedSegment]
    let activeLocation: ActiveWordLocation?
    let activeSegmentID: String?
    let onWordTap: (DiarizedSegment, Int, Int) -> Void

    var body: some View {
        ScrollViewReader { proxy in
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 16) {
                    ForEach(Array(segments.enumerated()), id: \.element.id) { idx, seg in
                        SpeakerTurnView(
                            speakerLabel: formatSpeakerLabel(seg.speakerId.rawValue),
                            words: TranscriptTabViewHelpers.buildWords(from: seg),
                            activeWordIndex: activeWordIndex(forSegmentIndex: idx),
                            onWordTap: { wordIdx in onWordTap(seg, idx, wordIdx) }
                        )
                        .id(seg.id)
                    }
                }
                .padding()
            }
            .onChange(of: activeSegmentID) { _, newID in
                guard let newID else { return }
                withAnimation(.easeInOut(duration: 0.3)) {
                    proxy.scrollTo(newID, anchor: .center)
                }
            }
        }
    }

    // MARK: - Helpers

    private func activeWordIndex(forSegmentIndex segmentIndex: Int) -> Int? {
        guard let loc = activeLocation, loc.segmentIndex == segmentIndex else { return nil }
        return loc.wordIndex
    }

    private func formatSpeakerLabel(_ rawValue: String) -> String {
        let parts = rawValue.split(separator: "-")
        if parts.count >= 2, let last = parts.last, last.allSatisfy(\.isNumber) {
            return "Speaker \(last)".uppercased()
        }
        return rawValue.uppercased()
    }
}

/// Composite storage protocol for meeting detail access.
public typealias MeetingDetailReadRepository = DiarizationReadRepository & NotesReadRepository & RecordingReadRepository & SummaryReadRepository
public typealias MeetingDetailWriteRepository = NotesWriteRepository & SummaryWriteRepository

import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

@Suite("MatchSpeakersUseCase")
struct MatchSpeakersUseCaseTests {
    @Test("matchSpeaker returns nil when no profiles exist")
    func matchReturnsNilWhenEmpty() async throws {
        let store = MockSpeakerProfileStore()
        let embedding = MockVoiceEmbeddingEngine()
        let useCase = MatchSpeakersUseCase(store: store, embedding: embedding)

        let result = try await useCase.matchSpeaker(samples: [Float](repeating: 0.5, count: 16000))

        #expect(result == nil)
    }

    @Test("matchSpeaker returns best match above threshold")
    func matchReturnsBestAboveThreshold() async throws {
        let store = MockSpeakerProfileStore()
        await store.setProfiles([
            SpeakerProfile(id: SpeakerID("p1"), name: "Alice", embedding: [1, 0, 0, 0]),
            SpeakerProfile(id: SpeakerID("p2"), name: "Bob", embedding: [0, 1, 0, 0]),
        ])
        let embedding = MockVoiceEmbeddingEngine()
        await embedding.setSimilarity(0.85)
        let useCase = MatchSpeakersUseCase(store: store, embedding: embedding, matchThreshold: 0.75)

        let result = try await useCase.matchSpeaker(samples: [Float](repeating: 0.5, count: 16000))

        #expect(result != nil)
        #expect(try #require(result?.confidence) > 0.84 && result!.confidence < 0.86)
    }

    @Test("matchSpeaker returns nil when below threshold")
    func matchReturnsNilBelowThreshold() async throws {
        let store = MockSpeakerProfileStore()
        await store.setProfiles([
            SpeakerProfile(id: SpeakerID("p1"), name: "Alice", embedding: [1, 0, 0, 0]),
        ])
        let embedding = MockVoiceEmbeddingEngine()
        await embedding.setSimilarity(0.5)
        let useCase = MatchSpeakersUseCase(store: store, embedding: embedding, matchThreshold: 0.75)

        let result = try await useCase.matchSpeaker(samples: [Float](repeating: 0.5, count: 16000))

        #expect(result == nil)
    }

    @Test("labelDiarization relabels segments with matched speakers")
    func labelDiarizationRelabels() async throws {
        let store = MockSpeakerProfileStore()
        await store.setProfiles([
            SpeakerProfile(id: SpeakerID("p1"), name: "Alice", embedding: [1, 0, 0, 0]),
        ])
        let embedding = MockVoiceEmbeddingEngine()
        await embedding.setSimilarity(0.9)
        let useCase = MatchSpeakersUseCase(store: store, embedding: embedding)

        let transcript = DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Hello",
                    speakerId: SpeakerID("spk_0"),
                    startTime: 0,
                    endTime: 1.0,
                    confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.1,
        )
        let samples = [Float](repeating: 0.5, count: 16000)

        let result = try await useCase.labelDiarization(transcript, audioSamples: samples)

        #expect(result.segments.first?.speakerId == SpeakerID("p1"))
    }

    @Test("duplicate display names produce distinct speaker IDs")
    func testDuplicateDisplayNamesProduceDistinctSpeakerIDs() async throws {
        let store = MockSpeakerProfileStore()
        await store.setProfiles([
            SpeakerProfile(id: SpeakerID("profile-aaa"), name: "John", embedding: [1, 0, 0, 0]),
            SpeakerProfile(id: SpeakerID("profile-bbb"), name: "John", embedding: [0, 1, 0, 0]),
        ])
        let embedding = MockVoiceEmbeddingEngine()
        await embedding.setSimilarity(0.9)
        let useCase = MatchSpeakersUseCase(store: store, embedding: embedding)

        let transcript = DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Hello from speaker zero",
                    speakerId: SpeakerID("spk_0"),
                    startTime: 0,
                    endTime: 1.0,
                    confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.1,
        )
        let samples = [Float](repeating: 0.5, count: 16000)

        let result = try await useCase.labelDiarization(transcript, audioSamples: samples)

        let relabeledId = try #require(result.segments.first?.speakerId)
        // The SpeakerID must come from the profile's ID, not the display name.
        // If the code uses the name, both profiles collapse to SpeakerID("John").
        #expect(
            relabeledId != SpeakerID("John"),
            "SpeakerID should be the profile ID, not the display name",
        )
        #expect(
            relabeledId == SpeakerID("profile-aaa"),
            "SpeakerID should match the matched profile's ID",
        )
    }
}

