        let relabeledId = try #require(result.segments.first?.speakerId)
        // The SpeakerID must come from the profile's ID, not the display name.
        // If the code uses the name, both profiles collapse to SpeakerID("John").
        #expect(
            relabeledId != SpeakerID("John"),
            "SpeakerID should be the profile ID, not the display name",
        )
        #expect(
            relabeledId == SpeakerID("profile-aaa"),
            "SpeakerID should match the matched profile's ID",
        )
    }
}

