import Testing
import Foundation
@testable import Business
import Domain

// MARK: - Factories

private func makeRecording(
    id: RecordingID = RecordingID("recording-001"),
    audioURL: URL = URL(fileURLWithPath: "/recordings/test-audio.wav"),
) -> StoredRecording {
    let meta = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: audioURL,
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuAndNeuralEngine,
        wordCount: 0,
    )
    return StoredRecording(metadata: meta)
}

/// Two speakers: spk_0 owns 0–2 s and 4–6 s (4 s total), spk_1 owns 2–4 s.
private func makeDiarization(wordTimings: [WordTimestamp]? = nil) -> DiarizedTranscript {
    DiarizedTranscript(
        segments: [
            DiarizedSegment(
                text: "Hello there", speakerId: SpeakerID("spk_0"),
                startTime: 0, endTime: 2, confidence: 0.9,
                wordTimings: wordTimings,
            ),
            DiarizedSegment(
                text: "Hi yourself", speakerId: SpeakerID("spk_1"),
                startTime: 2, endTime: 4, confidence: 0.9,
            ),
            DiarizedSegment(
                text: "How are you", speakerId: SpeakerID("spk_0"),
                startTime: 4, endTime: 6, confidence: 0.9,
            ),
        ],
        speakerCount: 2,
        processingTime: 0.5,
    )
}

private struct Fixture {
    let useCase: NameSpeakerUseCase
    let store: MockSpeakerProfileStore
    let embedding: MockVoiceEmbeddingEngine
    let storage: MockStorageEngine
    let recordingId: RecordingID
}

private func makeFixture(
    diarization: DiarizedTranscript = makeDiarization(),
    sampleSeconds: Double = 120,
) async throws -> Fixture {
    let recordingId = RecordingID("recording-001")
    let storage = MockStorageEngine()
    await storage.setMockStoredRecording(makeRecording(id: recordingId))
    await storage.setDiarization(diarization, for: recordingId)

    let loader = MockAudioSampleLoader()
    await loader.setMockSamples([Float](repeating: 0.5, count: Int(sampleSeconds * 16000)))

    let store = MockSpeakerProfileStore()
    let embedding = MockVoiceEmbeddingEngine()

    let useCase = NameSpeakerUseCase(
        store: store, embedding: embedding, sampleLoader: loader,
        reader: storage, writer: storage,
    )
    return Fixture(
        useCase: useCase, store: store, embedding: embedding,
        storage: storage, recordingId: recordingId,
    )
}

// MARK: - Tests

@Suite("NameSpeakerUseCase")
struct NameSpeakerUseCaseTests {

    @Test("naming a new speaker enrolls a profile and relabels their segments")
    func namesNewSpeaker() async throws {
        let fx = try await makeFixture()

        let segments = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let profiles = try await fx.store.allProfiles()
        let alice = try #require(profiles.first(where: { $0.name == "Alice" }))
        #expect(profiles.count == 1)

        let relabeled = segments.filter { $0.speakerId == alice.id }
        #expect(relabeled.count == 2, "both spk_0 segments must carry the profile id")
        #expect(segments.contains { $0.speakerId == SpeakerID("spk_1") }, "other speakers untouched")
        #expect(!segments.contains { $0.speakerId == SpeakerID("spk_0") })
    }

    @Test("naming persists the relabeled diarization via attachDiarization")
    func persistsRelabeledDiarization() async throws {
        let fx = try await makeFixture()

        _ = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let saved = try #require(await fx.storage.diarization(for: fx.recordingId))
        #expect(!saved.segments.contains { $0.speakerId == SpeakerID("spk_0") })
        #expect(saved.speakerCount == 2, "relabeling must not change speaker count")
    }

    @Test("naming with an existing profile name updates that profile instead of duplicating")
    func updatesExistingProfile() async throws {
        let fx = try await makeFixture()
        let existing = SpeakerProfile(name: "Alice", embedding: [1, 0, 0, 0], sampleCount: 1)
        await fx.store.setProfiles([existing])

        let segments = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let profiles = try await fx.store.allProfiles()
        #expect(profiles.count == 1, "must not create a duplicate profile")
        #expect(await fx.store.updateProfileCallCount == 1)
        #expect(segments.contains { $0.speakerId == existing.id })
    }

    @Test("relabeling preserves wordTimings")
    func preservesWordTimings() async throws {
        let timings = [
            WordTimestamp(word: "Hello", startTime: 0, endTime: 0.4, probability: 0.95),
            WordTimestamp(word: "there", startTime: 0.4, endTime: 0.9, probability: 0.9),
        ]
        let fx = try await makeFixture(diarization: makeDiarization(wordTimings: timings))

        let segments = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let first = try #require(segments.first(where: { $0.startTime == 0 }))
        #expect(first.wordTimings == timings)
    }

    @Test("throws insufficientAudio when the speaker has under one second of audio")
    func throwsOnShortAudio() async throws {
        let short = DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Hi", speakerId: SpeakerID("spk_0"),
                    startTime: 0, endTime: 0.4, confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.1,
        )
        let fx = try await makeFixture(diarization: short)

        await #expect(throws: SpeakerError.insufficientAudio) {
            _ = try await fx.useCase.nameSpeaker(
                recordingId: fx.recordingId,
                sourceSpeakerId: SpeakerID("spk_0"),
                name: "Alice",
            )
        }
    }

    @Test("throws insufficientAudio for a speaker not present in the transcript")
    func throwsOnUnknownSpeaker() async throws {
        let fx = try await makeFixture()

        await #expect(throws: SpeakerError.insufficientAudio) {
            _ = try await fx.useCase.nameSpeaker(
                recordingId: fx.recordingId,
                sourceSpeakerId: SpeakerID("spk_missing"),
                name: "Alice",
            )
        }
    }

    @Test("segment ranges beyond the loaded audio are clamped, not crashed")
    func clampsOutOfRangeSegments() async throws {
        // Audio is 3 s long but spk_0's second segment claims 4–6 s.
        let fx = try await makeFixture(sampleSeconds: 3)

        let segments = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )
        #expect(!segments.contains { $0.speakerId == SpeakerID("spk_0") })

        let extracted = try #require(await fx.embedding.lastExtractSamples)
        #expect(extracted.count == 2 * 16000, "only the in-range 0–2 s slice contributes")
    }

    @Test("enrollment audio is capped at 30 seconds")
    func capsEnrollmentAudio() async throws {
        let long = DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Monologue", speakerId: SpeakerID("spk_0"),
                    startTime: 0, endTime: 90, confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.5,
        )
        let fx = try await makeFixture(diarization: long)

        _ = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let extracted = try #require(await fx.embedding.lastExtractSamples)
        #expect(extracted.count <= 30 * 16000)
        #expect(extracted.count >= 16000)
    }
}

