    func capsEnrollmentAudio() async throws {
        let long = DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Monologue", speakerId: SpeakerID("spk_0"),
                    startTime: 0, endTime: 90, confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.5,
        )
        let fx = try await makeFixture(diarization: long)

        _ = try await fx.useCase.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("spk_0"),
            name: "Alice",
        )

        let extracted = try #require(await fx.embedding.lastExtractSamples)
        #expect(extracted.count <= 30 * 16000)
        #expect(extracted.count >= 16000)
    }
}

