import Foundation
import OSLog
import Domain

/// Names a diarized speaker in a meeting: enrolls (or updates) a voice profile
/// from that speaker's audio in the recording, relabels their segments to the
/// profile ID, and persists the relabeled diarization. Future meetings then
/// auto-label the speaker via `MatchSpeakersUseCase`.
public actor NameSpeakerUseCase {
    /// Enrollment quality guard: at least 1 s of the speaker's audio at 16 kHz.
    private static let minimumSamples = 16000
    /// Embedding-extraction cost cap: at most 30 s of the speaker's audio.
    private static let maximumSamples = 30 * 16000
    private static let sampleRate = 16000.0

    private let store: any SpeakerProfileStore
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository & DiarizationReadRepository
    private let writer: any DiarizationWriteRepository
    private let enroller: EnrollSpeakerUseCase
    private let logger = Logger(subsystem: "app.the-record", category: "NameSpeaker")

    public init(
        store: any SpeakerProfileStore,
        embedding: any VoiceEmbeddingEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository & DiarizationReadRepository,
        writer: any DiarizationWriteRepository,
    ) {
        self.store = store
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
        self.enroller = EnrollSpeakerUseCase(store: store, embedding: embedding)
    }

    /// Assigns `name` to the diarized speaker `sourceSpeakerId` in `recordingId`.
    /// - Returns: The relabeled segments (also persisted via `attachDiarization`).
    /// - Throws: `SpeakerError.insufficientAudio` if the speaker has under one
    ///   second of audio in the recording; `SpeakerError.invalidName` for
    ///   empty names; storage errors from the underlying repositories.
    public func nameSpeaker(
        recordingId: RecordingID,
        sourceSpeakerId: SpeakerID,
        name: String,
    ) async throws -> [DiarizedSegment] {
        let segments = try await reader.getSegments(id: recordingId)
        let recording = try await reader.getRecording(id: recordingId)
        let samples = try await sampleLoader.loadSamples(from: recording.metadata.audioURL)

        let speakerSamples = sliceSpeakerAudio(
            segments: segments, speakerId: sourceSpeakerId, samples: samples,
        )
        guard speakerSamples.count >= Self.minimumSamples else {
            throw SpeakerError.insufficientAudio
        }

        let profile = try await enrollOrUpdate(name: name, samples: speakerSamples)

        let relabeled = segments.map { seg in
            guard seg.speakerId == sourceSpeakerId else { return seg }
            return DiarizedSegment(
                text: seg.text, speakerId: profile.id,
                startTime: seg.startTime, endTime: seg.endTime,
                confidence: seg.confidence, wordTimings: seg.wordTimings,
            )
        }
        let speakerCount = Set(relabeled.map(\.speakerId)).count
        let diarization = DiarizedTranscript(
            segments: relabeled, speakerCount: speakerCount, processingTime: 0,
        )
        try await writer.attachDiarization(id: recordingId, diarization: diarization)

        logger.info(
            "Named speaker in \(recordingId.rawValue, privacy: .public) as '\(name, privacy: .private)'",
        )
        return relabeled
    }

    private func enrollOrUpdate(name: String, samples: [Float]) async throws -> SpeakerProfile {
        let existing = try await store.allProfiles()
        if let match = existing.first(where: { $0.name == name }) {
            return try await enroller.updateWithAdditionalSamples(
                profileId: match.id, newSamples: samples,
            )
        }
        return try await enroller.enroll(name: name, samples: samples)
    }

    /// Concatenates the speaker's audio ranges, clamped to the loaded sample
    /// buffer and capped at `maximumSamples`.
    private func sliceSpeakerAudio(
        segments: [DiarizedSegment], speakerId: SpeakerID, samples: [Float],
    ) -> [Float] {
        var collected: [Float] = []
        for seg in segments where seg.speakerId == speakerId {
            let start = max(0, min(Int(seg.startTime * Self.sampleRate), samples.count))
            let end = max(start, min(Int(seg.endTime * Self.sampleRate), samples.count))
            guard end > start else { continue }
            let remaining = Self.maximumSamples - collected.count
            guard remaining > 0 else { break }
            collected.append(contentsOf: samples[start ..< min(end, start + remaining)])
        }
        return collected
    }
}

