import Foundation
@testable import Business
import Domain

public actor MockDiarizationEngine: DiarizationEngine {

    // MARK: - Call tracking

    public var diarizeCalled = false
    public var diarizeCallCount = 0

    // MARK: - Configurable returns

    public var mockSegments: [SpeakerSegment]?
    public var errorToThrow: Error?

    public init() {}

    // MARK: - DiarizationEngine

    public func prepare() async throws {
        if let error = errorToThrow { throw error }
    }

    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        diarizeCalled = true
        diarizeCallCount += 1
        if let error = errorToThrow { throw error }
        return mockSegments ?? [
            SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0.0, endTime: 5.0, confidence: 0.9),
            SpeakerSegment(speakerId: SpeakerID("speaker-1"), startTime: 5.0, endTime: 10.0, confidence: 0.85),
        ]
    }

    public func isReady() async -> Bool {
        errorToThrow == nil
    }

    // MARK: - Test helpers

    public func setErrorToThrow(_ error: Error?) {
        errorToThrow = error
    }

    public func setMockSegments(_ segments: [SpeakerSegment]) {
        mockSegments = segments
    }
}

