import AVFoundation
import Domain
import FluidAudio
import Foundation
@testable import MLInfrastructure
import Testing

// MARK: - Helpers

private func chunk(
    speaker: String = "S0",
    axis: Int,
    scale: Float = 1,
    start: Double = 0,
    duration: Double = 10,
) -> ChunkEmbedding {
    var embedding = [Float](repeating: 0, count: 256)
    embedding[axis] = scale
    return ChunkEmbedding(
        speakerId: speaker,
        chunkIndex: 0,
        speakerIndex: 0,
        startTimeSeconds: start,
        endTimeSeconds: start + duration,
        embedding256: embedding,
    )
}

// MARK: - Unit tests (pure math, no models)

@Suite("FluidVoiceEmbedding centroid math")
struct FluidVoiceEmbeddingCentroidTests {

    @Test("empty chunk list yields the zero vector")
    func emptyChunksYieldZeroVector() {
        let centroid = FluidVoiceEmbeddingActor.weightedCentroid(of: [])
        #expect(centroid.count == 256)
        #expect(centroid.allSatisfy { $0 == 0 })
    }

    @Test("a single chunk yields its own direction, L2-normalized")
    func singleChunkIsNormalizedDirection() {
        let centroid = FluidVoiceEmbeddingActor.weightedCentroid(of: [chunk(axis: 0, scale: 5)])
        #expect(abs(centroid[0] - 1) < 1e-5)
        #expect(centroid.dropFirst().allSatisfy { $0 == 0 })
    }

    @Test("chunks are weighted by duration")
    func chunksAreDurationWeighted() {
        // 30 s on axis 0, 10 s on axis 1 → components in ratio 3:1, unit norm.
        let centroid = FluidVoiceEmbeddingActor.weightedCentroid(of: [
            chunk(axis: 0, duration: 30),
            chunk(axis: 1, start: 30, duration: 10),
        ])
        #expect(abs(centroid[0] / centroid[1] - 3) < 1e-4)
        let norm = sqrt(centroid.reduce(Float(0)) { $0 + $1 * $1 })
        #expect(abs(norm - 1) < 1e-5)
    }

    @Test("zero-norm and zero-duration chunks are skipped")
    func degenerateChunksAreSkipped() {
        let centroid = FluidVoiceEmbeddingActor.weightedCentroid(of: [
            chunk(axis: 0, scale: 0),               // zero vector
            chunk(axis: 1, duration: 0),            // zero duration
            chunk(axis: 2, duration: 10),           // the only valid chunk
        ])
        #expect(abs(centroid[2] - 1) < 1e-5)
    }

    @Test("cosine similarity: identical vectors 1, orthogonal 0, mismatched lengths 0")
    func cosineSimilarityBasics() async {
        let engine = FluidVoiceEmbeddingActor()
        var a = [Float](repeating: 0, count: 256)
        a[0] = 1
        var b = [Float](repeating: 0, count: 256)
        b[1] = 1
        #expect(abs(await engine.cosineSimilarity(a, a) - 1) < 1e-5)
        #expect(abs(await engine.cosineSimilarity(a, b)) < 1e-5)
        #expect(await engine.cosineSimilarity(a, [1, 0]) == 0)
    }
}

// MARK: - Integration (real FluidAudio inference)

@Suite(
    "FluidVoiceEmbedding integration",
    .enabled(if: ProcessInfo.processInfo.environment["RUN_INTEGRATION_TESTS"] != nil),
)
struct FluidVoiceEmbeddingIntegrationTests {

    private static let fixtureURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // Unit
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // Record-ML
        .deletingLastPathComponent()  // repo root
        .appendingPathComponent("Data/diarization-fixtures/meeting-15min.wav")

    private func loadFixtureSamples(seconds: Range<Double>) throws -> [Float] {
        let file = try AVAudioFile(forReading: Self.fixtureURL)
        let rate = file.processingFormat.sampleRate
        file.framePosition = AVAudioFramePosition(seconds.lowerBound * rate)
        let frames = AVAudioFrameCount((seconds.upperBound - seconds.lowerBound) * rate)
        guard
            let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: frames)
        else { throw CocoaError(.fileReadUnknown) }
        try file.read(into: buffer, frameCount: frames)
        guard let data = buffer.floatChannelData else { throw CocoaError(.fileReadUnknown) }
        return Array(UnsafeBufferPointer(start: data[0], count: Int(buffer.frameLength)))
    }

    @Test("extract returns a deterministic non-zero unit vector on real speech")
    func extractIsDeterministicUnitVector() async throws {
        let engine = FluidVoiceEmbeddingActor()
        let samples = try loadFixtureSamples(seconds: 10 ..< 25)

        let first = await engine.extract(from: samples)
        let second = await engine.extract(from: samples)

        #expect(first.count == 256)
        let norm = sqrt(first.reduce(Float(0)) { $0 + $1 * $1 })
        #expect(abs(norm - 1) < 1e-3, "embedding must be L2-normalized and non-zero")
        #expect(await engine.cosineSimilarity(first, second) > 0.999, "extraction must be deterministic")
    }

    @Test("empty audio degrades to the zero vector instead of crashing")
    func emptyAudioYieldsZeroVector() async {
        let engine = FluidVoiceEmbeddingActor()
        let vector = await engine.extract(from: [])
        #expect(vector.allSatisfy { $0 == 0 })
    }
}

