import Domain
import FluidAudio
import Foundation
import Logging

/// `VoiceEmbeddingEngine` backed by FluidAudio's 256-dim conformer speaker
/// embeddings — the same embedding space `OfflineDiarizationPlugin` clusters
/// in, so enrolled profiles and diarized speakers are directly comparable.
///
/// `extract(from:)` runs the offline diarizer over the clip with chunk
/// embeddings exposed and returns the duration-weighted L2-normalized
/// centroid across all chunks (all speakers — enrollment clips are assumed
/// to be a single speaker's audio).
public actor FluidVoiceEmbeddingActor: VoiceEmbeddingEngine {
    public static let embeddingDimension = 256

    private static let logger = AppLogger.for(category: "FluidVoiceEmbedding")

    public init() {}

    /// `OfflineDiarizerManager` is not `Sendable`; build a region-local one
    /// per call (same pattern as `OfflineDiarizationPlugin`).
    public func extract(from samples: [Float]) async -> [Float] {
        guard !samples.isEmpty else {
            return [Float](repeating: 0, count: Self.embeddingDimension)
        }
        do {
            var config = OfflineDiarizerConfig()
            config.exposeChunkEmbeddings = true
            let manager = OfflineDiarizerManager(config: config)
            try await manager.prepareModels()
            let result = try await manager.process(audio: samples)
            return Self.weightedCentroid(of: result.chunkEmbeddings ?? [])
        } catch {
            Self.logger.error("Embedding extraction failed, returning zero vector: \(error)")
            return [Float](repeating: 0, count: Self.embeddingDimension)
        }
    }

    public func cosineSimilarity(_ a: [Float], _ b: [Float]) async -> Float {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot: Float = 0
        var normA: Float = 0
        var normB: Float = 0
        for i in 0 ..< a.count {
            dot += a[i] * b[i]
            normA += a[i] * a[i]
            normB += b[i] * b[i]
        }
        let denominator = (normA * normB).squareRoot()
        return denominator > 0 ? dot / denominator : 0
    }

    /// Duration-weighted centroid of per-chunk L2-normalized embeddings,
    /// L2-normalized again so cosine comparisons are scale-free. Zero-norm
    /// and zero-duration chunks are skipped; no valid chunks → zero vector.
    static func weightedCentroid(of chunks: [ChunkEmbedding]) -> [Float] {
        var sum = [Double](repeating: 0, count: embeddingDimension)
        var totalDuration = 0.0
        for chunk in chunks {
            let duration = chunk.endTimeSeconds - chunk.startTimeSeconds
            guard duration > 0, chunk.embedding256.count == embeddingDimension else { continue }
            let norm = chunk.embedding256.reduce(0.0) { $0 + Double($1) * Double($1) }.squareRoot()
            guard norm > 0 else { continue }
            for i in 0 ..< embeddingDimension {
                sum[i] += Double(chunk.embedding256[i]) / norm * duration
            }
            totalDuration += duration
        }
        guard totalDuration > 0 else {
            return [Float](repeating: 0, count: embeddingDimension)
        }
        let sumNorm = sum.reduce(0.0) { $0 + $1 * $1 }.squareRoot()
        guard sumNorm > 0 else {
            return [Float](repeating: 0, count: embeddingDimension)
        }
        return sum.map { Float($0 / sumNorm) }
    }
}

