import Domain
import SwiftUI

// MARK: - TranscriptSpeakerScrollView
//
// The speaker-turn scroll area extracted from TranscriptTabView to satisfy the
// 150-line file-size limit. Renders one SpeakerTurnView per DiarizedSegment and
// auto-scrolls to keep the active segment visible during playback.
//
// Scroll sync (OBS-005-scroll): `onChange(of: activeSegmentID)` fires whenever
// the active playback location crosses a segment boundary. The animated scroll
// targets `.center` anchor so the active turn stays readable without jumping to
// the top or bottom of the viewport.

@MainActor
struct TranscriptSpeakerScrollView: View {
    let segments: [DiarizedSegment]
    let activeLocation: ActiveWordLocation?
    let activeSegmentID: String?
    let onWordTap: (DiarizedSegment, Int, Int) -> Void

    var body: some View {
        ScrollViewReader { proxy in
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 16) {
                    ForEach(Array(segments.enumerated()), id: \.element.id) { idx, seg in
                        SpeakerTurnView(
                            speakerLabel: formatSpeakerLabel(seg.speakerId.rawValue),
                            words: TranscriptTabViewHelpers.buildWords(from: seg),
                            activeWordIndex: activeWordIndex(forSegmentIndex: idx),
                            onWordTap: { wordIdx in onWordTap(seg, idx, wordIdx) }
                        )
                        .id(seg.id)
                    }
                }
                .padding()
            }
            .onChange(of: activeSegmentID) { _, newID in
                guard let newID else { return }
                withAnimation(.easeInOut(duration: 0.3)) {
                    proxy.scrollTo(newID, anchor: .center)
                }
            }
        }
    }

    // MARK: - Helpers

    private func activeWordIndex(forSegmentIndex segmentIndex: Int) -> Int? {
        guard let loc = activeLocation, loc.segmentIndex == segmentIndex else { return nil }
        return loc.wordIndex
    }

    private func formatSpeakerLabel(_ rawValue: String) -> String {
        let parts = rawValue.split(separator: "-")
        if parts.count >= 2, let last = parts.last, last.allSatisfy(\.isNumber) {
            return "Speaker \(last)".uppercased()
        }
        return rawValue.uppercased()
    }
}

import Domain
import Logging
import SwiftUI

// MARK: - TranscriptTabView
//
// Speaker-attributed, word-tappable transcript display with audio playback.
//
// Design choice: AudioPlayerViewModel is passed as a parameter (not created internally)
// so the caller controls the driver (Infrastructure), preserving the strict layer rule
// that Presentation never imports Infrastructure. The owner creates the VM and passes it.
//
// INV-007: View is never blank — shows speaker turns OR flat-text fallback (COMPAT-004).
// OBS-005: Word tap logged at DEBUG: recording_id (privacy: .private), word_index, seek_time.

@MainActor
public struct TranscriptTabView: View {
    @Bindable public var viewModel: MeetingDetailViewModel
    public var audioPlayerViewModel: AudioPlayerViewModel

    private let logger = AppLogger.for(category: "TranscriptTab")

    public init(viewModel: MeetingDetailViewModel, audioPlayerViewModel: AudioPlayerViewModel) {
        self.viewModel = viewModel
        self.audioPlayerViewModel = audioPlayerViewModel
    }

    // MARK: - Derived state

    private var activeLocation: ActiveWordLocation? {
        TranscriptTabViewHelpers.activeLocation(
            in: viewModel.segments,
            at: audioPlayerViewModel.currentTime
        )
    }

    // MARK: - Body

    public var body: some View {
        VStack(spacing: 0) {
            if viewModel.segments.isEmpty {
                // COMPAT-004: no diarized segments — fall back to flat transcript text.
                ScrollView {
                    VStack(alignment: .leading) {
                        if let transcript = viewModel.transcript, !transcript.isEmpty {
                            Text(transcript)
                                .font(.body)
                                .textSelection(.enabled)
                                .frame(maxWidth: .infinity, alignment: .leading)
                        } else {
                            Text("No transcript available")
                                .font(.body)
                                .foregroundStyle(.secondary)
                                .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
            } else {
                // Compute the O(n) active-word scan once per body evaluation and
                // derive the active segment id from its result — the body runs on
                // every 30 fps playback tick, so a second scan is pure waste.
                let location = activeLocation
                TranscriptSpeakerScrollView(
                    segments: viewModel.segments,
                    activeLocation: location,
                    activeSegmentID: TranscriptTabViewHelpers.segmentID(for: location, in: viewModel.segments),
                    onWordTap: handleWordTap
                )
            }
            Divider()
            AudioPlayerBar(viewModel: audioPlayerViewModel)
        }
        .onChange(of: viewModel.selectedMeeting?.id) { _, _ in
            // OBS-005 / SAFE-005: load audio for the newly selected meeting.
            // loadGracefully swallows errors and logs at ERROR (ORD-003).
            if let url = viewModel.audioURL {
                audioPlayerViewModel.loadGracefully(url: url)
            }
        }
    }

    // MARK: - Word tap

    private func handleWordTap(segment: DiarizedSegment, segmentIndex: Int, wordIndex: Int) {
        let seekTime: TimeInterval
        if let wordTimings = segment.wordTimings, wordIndex < wordTimings.count {
            seekTime = wordTimings[wordIndex].startTime
        } else {
            seekTime = segment.startTime
        }
        let recordingID = viewModel.selectedMeeting?.id.rawValue ?? "unknown"
        logger.debug(
            "word tap — recording_id=\(recordingID, privacy: .private) word_index=\(wordIndex, privacy: .public) seek_time=\(seekTime, privacy: .public)"
        )
        audioPlayerViewModel.seek(to: seekTime)
    }
}

