        let profile = SpeakerProfile(name: "Alice", embedding: [1, 0], sampleCount: 1)
        await fx.store.setProfiles([profile])

        await fx.viewModel.loadProfiles()

        #expect(fx.viewModel.speakerNames[profile.id.rawValue] == "Alice")
    }

