    func displayLabelResolution() async {
        let fx = await makeFixture()
        let profile = SpeakerProfile(name: "Alice", embedding: [1, 0], sampleCount: 1)
        await fx.store.setProfiles([profile])
        await fx.viewModel.loadProfiles()

        #expect(fx.viewModel.displayLabel(for: profile.id) == "ALICE")
        #expect(fx.viewModel.displayLabel(for: SpeakerID("speaker-0")) == "SPEAKER 0")
        #expect(fx.viewModel.displayLabel(for: SpeakerID("Bob")) == "BOB")
    }

    @Test("canNameSpeakers is false without an injected use case")
    func canNameSpeakersFalseWithoutUseCase() {
        let viewModel = SpeakerNamingViewModel(profileStore: MockSpeakerProfileStore())
        #expect(!viewModel.canNameSpeakers)
    }

    @Test("nameSpeaker success returns segments and refreshes the name map")
    func nameSpeakerSuccess() async throws {
        let fx = await makeFixture()

        let segments = await fx.viewModel.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("speaker-0"),
            name: "Alice",
        )

        let returned = try #require(segments)
        #expect(!returned.contains { $0.speakerId == SpeakerID("speaker-0") })
        #expect(fx.viewModel.speakerNames.values.contains("Alice"), "name map must refresh after enrollment")
        #expect(fx.viewModel.errorMessage == nil)
    }

    @Test("nameSpeaker failure surfaces an error message and returns nil")
    func nameSpeakerFailureSurfacesError() async {
        // 0.3 s of speaker audio — under the 1 s enrollment minimum.
        let fx = await makeFixture(speakerSeconds: 0.3)

        let segments = await fx.viewModel.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("speaker-0"),
            name: "Alice",
        )

        #expect(segments == nil)
        #expect(fx.viewModel.errorMessage != nil)
    }
}

