import Business
import Domain
import Foundation
import Logging
import Observation

// MARK: - SpeakerNamingViewModel
//
// Owns the "name a speaker from a meeting" flow (#300): resolves diarized
// speaker IDs to enrolled profile names for transcript display, and drives
// the naming alert that enrolls a speaker's voice from the current meeting.
//
// Separate from MeetingDetailViewModel (at its 200-line cap); the owning view
// refreshes segments through MeetingDetailViewModel after a successful rename.

@MainActor
@Observable
public final class SpeakerNamingViewModel {
    /// Profile ID rawValue → enrolled display name, for transcript labels.
    public private(set) var speakerNames: [String: String] = [:]

    /// The diarized speaker currently being named; non-nil drives the alert.
    public var namingTarget: SpeakerID?
    /// TextField binding for the alert.
    public var pendingName: String = ""
    public private(set) var errorMessage: String?
    public private(set) var isNaming = false

    private let profileStore: any SpeakerProfileStore
    private let nameSpeakerUseCase: NameSpeakerUseCase?
    private let logger = AppLogger.for(category: "SpeakerNaming")

    /// Whether the naming affordance should be shown at all — false when the
    /// composition root did not wire the use case (feature unavailable).
    public var canNameSpeakers: Bool { nameSpeakerUseCase != nil }

    public init(
        profileStore: any SpeakerProfileStore,
        nameSpeakerUseCase: NameSpeakerUseCase? = nil,
    ) {
        self.profileStore = profileStore
        self.nameSpeakerUseCase = nameSpeakerUseCase
    }

    public func loadProfiles() async {
        do {
            let profiles = try await profileStore.allProfiles()
            speakerNames = Dictionary(
                uniqueKeysWithValues: profiles.map { ($0.id.rawValue, $0.name) },
            )
        } catch {
            logger.error("Failed to load speaker profiles: \(error)")
        }
    }

    /// Display label for a transcript speaker: the enrolled profile name when
    /// known, otherwise the legacy "SPEAKER N" formatting.
    public func displayLabel(for speakerId: SpeakerID) -> String {
        if let name = speakerNames[speakerId.rawValue] {
            return name.uppercased()
        }
        return Self.formatSpeakerLabel(speakerId.rawValue)
    }

    /// Formats a raw diarizer speaker ID ("speaker-0") as "SPEAKER 0";
    /// anything else is uppercased verbatim.
    public static func formatSpeakerLabel(_ rawValue: String) -> String {
        let parts = rawValue.split(separator: "-")
        if parts.count >= 2, let last = parts.last, last.allSatisfy(\.isNumber) {
            return "Speaker \(last)".uppercased()
        }
        return rawValue.uppercased()
    }

    /// Enrolls `sourceSpeakerId`'s voice from the recording under `name` and
    /// relabels their segments.
    /// - Returns: The relabeled segments on success (caller refreshes the
    ///   transcript), or nil on failure with `errorMessage` set.
    @discardableResult
    public func nameSpeaker(
        recordingId: RecordingID,
        sourceSpeakerId: SpeakerID,
        name: String,
    ) async -> [DiarizedSegment]? {
        guard let nameSpeakerUseCase else { return nil }
        isNaming = true
        errorMessage = nil
        defer { isNaming = false }
        do {
            let segments = try await nameSpeakerUseCase.nameSpeaker(
                recordingId: recordingId,
                sourceSpeakerId: sourceSpeakerId,
                name: name,
            )
            await loadProfiles()
            return segments
        } catch {
            logger.error("Naming speaker failed: \(error)")
            errorMessage = Self.message(for: error)
            return nil
        }
    }

    public func clearError() {
        errorMessage = nil
    }

    private static func message(for error: Error) -> String {
        switch error {
        case SpeakerError.insufficientAudio:
            return "Not enough of this speaker's audio in the meeting to learn their voice (need at least 1 second)."
        case SpeakerError.invalidName:
            return "Please enter a name."
        default:
            return "Could not name this speaker. Please try again."
        }
    }
}

