import Domain
import SwiftUI

// MARK: - SpeakerNameAlert
//
// Alert flow for naming a diarized speaker (#300): a TextField alert driven
// by SpeakerNamingViewModel.namingTarget, plus an error alert for failures
// (e.g. not enough of the speaker's audio to enroll a voice profile).

@MainActor
struct SpeakerNameAlert: ViewModifier {
    @Bindable var namingVM: SpeakerNamingViewModel
    let recordingId: RecordingID?
    /// Called with the relabeled segments after a successful rename.
    let onRenamed: ([DiarizedSegment]) -> Void

    func body(content: Content) -> some View {
        content
            .alert(
                String(localized: "Name Speaker"),
                isPresented: isNamingPresented,
            ) {
                TextField(String(localized: "Name"), text: $namingVM.pendingName)
                Button(String(localized: "Save")) { submit() }
                    .disabled(namingVM.pendingName.trimmingCharacters(in: .whitespaces).isEmpty)
                Button(String(localized: "Cancel"), role: .cancel) {
                    namingVM.namingTarget = nil
                }
            } message: {
                Text(String(localized: "Learns this speaker's voice from the meeting so future meetings label them automatically."))
            }
            .alert(
                String(localized: "Could Not Name Speaker"),
                isPresented: isErrorPresented,
            ) {
                Button(String(localized: "OK")) { namingVM.clearError() }
            } message: {
                Text(namingVM.errorMessage ?? "")
            }
    }

    private var isNamingPresented: Binding<Bool> {
        Binding(
            get: { namingVM.namingTarget != nil },
            set: { if !$0 { namingVM.namingTarget = nil } },
        )
    }

    private var isErrorPresented: Binding<Bool> {
        Binding(
            get: { namingVM.errorMessage != nil },
            set: { if !$0 { namingVM.clearError() } },
        )
    }

    private func submit() {
        guard let recordingId, let target = namingVM.namingTarget else { return }
        let name = namingVM.pendingName.trimmingCharacters(in: .whitespaces)
        namingVM.namingTarget = nil
        namingVM.pendingName = ""
        Task {
            if let segments = await namingVM.nameSpeaker(
                recordingId: recordingId, sourceSpeakerId: target, name: name,
            ) {
                onRenamed(segments)
            }
        }
    }
}

extension View {
    /// Attaches the speaker-naming alert flow (#300).
    func speakerNameAlert(
        namingVM: SpeakerNamingViewModel,
        recordingId: RecordingID?,
        onRenamed: @escaping ([DiarizedSegment]) -> Void,
    ) -> some View {
        modifier(SpeakerNameAlert(namingVM: namingVM, recordingId: recordingId, onRenamed: onRenamed))
    }
}

