// MARK: - Factories

private func makeRecording(id: RecordingID) -> StoredRecording {
    let meta = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: URL(fileURLWithPath: "/recordings/test-audio.wav"),
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuAndNeuralEngine,
        wordCount: 0,
    )
    return StoredRecording(metadata: meta)
}

private struct Fixture {
    let viewModel: SpeakerNamingViewModel
    let store: MockSpeakerProfileStore
    let recordingId: RecordingID
}

@MainActor
private func makeFixture(speakerSeconds: Double = 5) async -> Fixture {
    let recordingId = RecordingID("recording-001")
    let storage = MockStorageEngine()
    await storage.setMockStoredRecording(makeRecording(id: recordingId))
    await storage.setDiarization(
        DiarizedTranscript(
            segments: [
                DiarizedSegment(
                    text: "Hello", speakerId: SpeakerID("speaker-0"),
                    startTime: 0, endTime: speakerSeconds, confidence: 0.9,
                ),
            ],
            speakerCount: 1,
            processingTime: 0.1,
        ),
        for: recordingId,
    )
    let loader = MockAudioSampleLoader()
    await loader.setMockSamples([Float](repeating: 0.5, count: 120 * 16000))

    let store = MockSpeakerProfileStore()
    let useCase = NameSpeakerUseCase(
        store: store, embedding: MockVoiceEmbeddingEngine(), sampleLoader: loader,
        reader: storage, writer: storage,
    )
    let viewModel = SpeakerNamingViewModel(profileStore: store, nameSpeakerUseCase: useCase)
    return Fixture(viewModel: viewModel, store: store, recordingId: recordingId)
}

// MARK: - Tests

@MainActor
@Suite("SpeakerNamingViewModel")
struct SpeakerNamingViewModelTests {

    @Test("loadProfiles builds the profileId → name map")
    func loadProfilesBuildsNameMap() async throws {
        let fx = await makeFixture()
        let profile = SpeakerProfile(name: "Alice", embedding: [1, 0], sampleCount: 1)
        await fx.store.setProfiles([profile])

        await fx.viewModel.loadProfiles()

        #expect(fx.viewModel.speakerNames[profile.id.rawValue] == "Alice")
    }

    @Test("displayLabel resolves enrolled names, falls back to Speaker N formatting")
    func displayLabelResolution() async {
        let fx = await makeFixture()
        let profile = SpeakerProfile(name: "Alice", embedding: [1, 0], sampleCount: 1)
        await fx.store.setProfiles([profile])
        await fx.viewModel.loadProfiles()

        #expect(fx.viewModel.displayLabel(for: profile.id) == "ALICE")
        #expect(fx.viewModel.displayLabel(for: SpeakerID("speaker-0")) == "SPEAKER 0")
        #expect(fx.viewModel.displayLabel(for: SpeakerID("Bob")) == "BOB")
    }

    @Test("canNameSpeakers is false without an injected use case")
    func canNameSpeakersFalseWithoutUseCase() {
        let viewModel = SpeakerNamingViewModel(profileStore: MockSpeakerProfileStore())
        #expect(!viewModel.canNameSpeakers)
    }

    @Test("nameSpeaker success returns segments and refreshes the name map")
    func nameSpeakerSuccess() async throws {
        let fx = await makeFixture()

        let segments = await fx.viewModel.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("speaker-0"),
            name: "Alice",
        )

        let returned = try #require(segments)
        #expect(!returned.contains { $0.speakerId == SpeakerID("speaker-0") })
        #expect(fx.viewModel.speakerNames.values.contains("Alice"), "name map must refresh after enrollment")
        #expect(fx.viewModel.errorMessage == nil)
    }

    @Test("nameSpeaker failure surfaces an error message and returns nil")
    func nameSpeakerFailureSurfacesError() async {
        // 0.3 s of speaker audio — under the 1 s enrollment minimum.
        let fx = await makeFixture(speakerSeconds: 0.3)

        let segments = await fx.viewModel.nameSpeaker(
            recordingId: fx.recordingId,
            sourceSpeakerId: SpeakerID("speaker-0"),
            name: "Alice",
        )

        #expect(segments == nil)
        #expect(fx.viewModel.errorMessage != nil)
    }
}

